// deps: 4948, 46173, 99808, 27214, 14029, 75435, 34988, 29979, 83593, 10414, 84726, 20544, 74738, 33922, 29804, 30610, 33058, 7404, 89095, 90149, 2085, 36970, 62391, 74097, 37880, 8156
const module_59965 = (e,a,n)=>{"use strict";n.r(a),n.d(a,{default:()=>A});var i=n(4948),t=n(46173),r=n(99808),o=n(27214),s=n(14029),l=n(75435),d=n(34988),c=n(29979),u=n(83593);let m=JSON.parse('[{"key":"tangtang","name":"Tangtang","codename":"Tangtang","camp":"Endfield Industries","race":"Felino","rarity":6,"intro":"\\"Sua Chefe Suprema est\xe1 aqui! Voc\xea, voc\xea e voc\xea est\xe3o todos sob meu comando!\\" \\nTangtang, a Chefe Suprema da Pali\xe7ada de Qingbo. Ela \xe9 direta, valoriza a lealdade e age com um esp\xedrito livre e desinibido. Ama a liberdade e brincar na \xe1gua, mas detesta trai\xe7\xe3o. Uma vez que reconhe\xe7a voc\xea como amigo, far\xe1 de tudo para ajudar. \\nAinda beb\xea, Tangtang foi colocada em uma cesta de bambu por um desconhecido e levada pela correnteza do rio at\xe9 a Pali\xe7ada de Qingbo, onde foi adotada pelos Pali\xe7ados e se tornou uma deles. Aos olhos de muitos, ela ainda \xe9 uma crian\xe7a que precisa de carinho, mas em seu cora\xe7\xe3o, ela j\xe1 decidiu h\xe1 muito tempo contribuir para o futuro da Pali\xe7ada de Qingbo. \\nMesmo tendo enfrentado muitos contratempos, permanece apaixonada pelo mundo. Para encontrar respostas para suas perguntas e contribuir para o desenvolvimento da Pali\xe7ada de Qingbo, Tangtang se juntou \xe0 Endfield Industries. \\n\\"Mantenha-a longe de Mi Fu, ou as coisas podem quebrar\\" — disse um operador do Escrit\xf3rio de Log\xedstica Principal. \\n\\"Voc\xea me chamou s\xf3 para me elogiar? Ent\xe3o, n\xe3o economize nos elogios. Adoro ouvir a verdade!\\"","prof":"caster","elem":"ice","cv":{"en-us":"Jing Chen"}},{"key":"rossi","name":"Rossi","codename":"Rossi","camp":"Endfield Industries","race":"Lupo","rarity":6,"intro":"\\"Moleza para algu\xe9m da elite como eu!\\" \\nRossina Wulfperl Luppino, irm\xe3 mais nova de Wulfgard e a P\xe9rola da Matilha. Em um feudo entre a Matilha e os Quebra-Ossos, muitos lobos anci\xe3os pagaram um pre\xe7o muito alto para resgat\xe1-la. O sangue daquele dia manchou de vermelho o cobertor em que ela estava enrolada... \\nWulfgard opera independentemente do cl\xe3 por anos, mas a Matilha precisava de um l\xedder, e Rossi aceitou essa responsabilidade. Ela sempre sentiu que seu irm\xe3o, que ascendeu \xe0 fama ainda jovem, deveria ser o l\xedder de toda a Matilha, e constantemente o lembra e o incentiva a faz\xea-lo. Embora os anci\xe3os do cl\xe3 esperem que Rossi possa passar mais tempo fazendo o que ama em sua idade, ela, no fim das contas, n\xe3o consegue se livrar do peso da \\"responsabilidade\\". Ela se esfor\xe7a para se tornar mais confi\xe1vel e poderosa pelo bem de sua fam\xedlia e do cl\xe3. \\nRossi, que anseia por hist\xf3rias heroicas, ocasionalmente fantasia que um dia poder\xe1 lutar ao lado de um her\xf3i lend\xe1rio. Este \xe9 o seu momento de \\"tempo para si mesma\\". \\n\\"Eles mordem muito fundo, mas a Matilha n\xe3o tem medo de mais cicatrizes!\\"","prof":"guard","elem":"physic","cv":{"en-us":"Giada Sabellico"}},{"key":"endministrator2","name":"Endministrator","codename":"Endministrator","camp":"Endfield Industries","race":"N\xe3o divulgado","rarity":6,"intro":"O Endministrator da Endfield Industries.\\nNa hist\xf3ria registrada de Talos-II, o Endministrator \xe9 um guardi\xe3o fundamental que protegeu a civiliza\xe7\xe3o neste planeta e salvou a humanidade de in\xfameros desastres catastr\xf3ficos. Os feitos heroicos de Endmin deram origem a muitas hist\xf3rias, contos e at\xe9 rumores. \\nNo entanto, a identidade de Endmin permanece desconhecida e apenas algumas pessoas j\xe1 tiveram a oportunidade de conhecer a lenda pessoalmente. \\nOutras fac\xe7\xf5es dentro do Cintur\xe3o da Civiliza\xe7\xe3o sabem muito bem que a Endfield tem um trunfo muito especial em m\xe3os, mas isso \xe9 tudo o que sabem. \\nO misterioso dom\xednio do Endministrator sobre o Originium e a Rede do Protocolo, juntamente com a necessidade de hibernar periodicamente por longos per\xedodos, \xe9 um dos segredos mais importantes da Endfield.","prof":"guard","elem":"physic","cv":{"en-us":"Hyoie O\'Grady"}},{"key":"endministrator1","name":"Endministrator","codename":"Endministrator","camp":"Endfield Industries","race":"N\xe3o divulgado","rarity":6,"intro":"O Endministrator da Endfield Industries.\\nNa hist\xf3ria registrada de Talos-II, o Endministrator \xe9 um guardi\xe3o fundamental que protegeu a civiliza\xe7\xe3o neste planeta e salvou a humanidade de in\xfameros desastres catastr\xf3ficos. Os feitos heroicos de Endmin deram origem a muitas hist\xf3rias, contos e at\xe9 rumores. \\nNo entanto, a identidade de Endmin permanece desconhecida e apenas algumas pessoas j\xe1 tiveram a oportunidade de conhecer a lenda pessoalmente. \\nOutras fac\xe7\xf5es dentro do Cintur\xe3o da Civiliza\xe7\xe3o sabem muito bem que a Endfield tem um trunfo muito especial em m\xe3os, mas isso \xe9 tudo o que sabem. \\nO misterioso dom\xednio do Endministrator sobre o Originium e a Rede do Protocolo, juntamente com a necessidade de hibernar periodicamente por longos per\xedodos, \xe9 um dos segredos mais importantes da Endfield.","prof":"guard","elem":"physic","cv":{"en-us":"Chloe Eves"}},{"key":"perlica","name":"Perlica","codename":"Perlica","camp":"Endfield Industries","race":"Liberi","rarity":5,"intro":"\\"Lutamos e nunca desistimos... pois \xe9 nosso desejo testemunhar o seu retorno.\\" \\nPerlica \xe9 a Supervisora da Endfield Industries e porta-voz oficial da empresa. Ela \xe9 a principal respons\xe1vel por supervisionar e promover o desenvolvimento e a aplica\xe7\xe3o da tecnologia de Protocolo-Originium, al\xe9m de gerenciar as opera\xe7\xf5es da Dijiang. \\nComo especialista excepcional em Tecnoprotocolo, ela orientou pesquisas que tiveram uma influ\xeancia fundamental no desenvolvimento adaptativo e na aplica\xe7\xe3o da tecnologia e ajudou a refinar o Complexo Automatizado Industrial (F\xe1brica do CAI). \\nEla \xe9 capaz de responder a diversas crises com calma e decis\xe3o. No entanto, a Endfield frequentemente enfrenta desafios que v\xe3o al\xe9m de todas as expectativas. Enquanto o Endministrator permanecia em hiberna\xe7\xe3o, ela assumiu o comando da Equipe de Crises, liderando os her\xf3is da Endfield Industries em uma batalha por uma causa maior. Perlica se move incansavelmente pelo Cintur\xe3o da Civiliza\xe7\xe3o, fazendo tudo o que pode para manter a ordem e manter as coisas funcionando. \\n\\n\\"Somente caminhando sobre a terra podemos realmente apreciar cada respira\xe7\xe3o e pulsa\xe7\xe3o da vida... E \xe9 por isso que a Endfield est\xe1 lutando.\\"","prof":"caster","elem":"electric","cv":{"en-us":"Jane Jackson"}},{"key":"chen","name":"Chen Qianyu","codename":"Chen Qianyu","camp":"Endfield Industries","race":"Lung","rarity":5,"intro":"\\"Pois \xe9, descobri que sou \xf3tima em outras coisas al\xe9m de artes marciais. \xc9 imposs\xedvel n\xe3o acabar sendo a sua melhor operadora.\\" \\nChen Qianyu \xe9 operadora na Endfield Industries e membro essencial da Equipe de Crises. \\nDesde jovem, treinou artes marciais sob a orienta\xe7\xe3o de sua m\xe3e e no Tanjian Hall. Sua dedica\xe7\xe3o rendeu a ela excelentes habilidades de combate e uma fortaleza mental raramente vista entre seus pares. Embora nunca tenha visto a lend\xe1ria Chi Xiao, ela orgulhosamente mant\xe9m seu Dom\xednio da Espada Chi Xiao, desenvolvido por si mesma, e a empunha em nome da justi\xe7a. \\nDepois de anos vagando por Talos-II sozinha com sua espada, Chen Qianyu se juntou \xe0 Endfield a convite de Perlica. Sua natureza otimista e seu entusiasmo feroz a levam a encarar todos os desafios urgentes sem hesita\xe7\xe3o. \\n\\n\\"Dizem que a l\xe2mina da minha m\xe3e agitou as pr\xf3prias nuvens, Endmin. E eu farei exatamente isso... e me tornarei aquela com quem voc\xea e Perlica sempre poder\xe3o contar!\\"","prof":"guard","elem":"physic","cv":{"en-us":"Rebecca Hanssen"}},{"key":"laevatain","name":"Laevatain","codename":"Laevatain","camp":"Rhodes Island","race":"Sarkaz","rarity":6,"intro":"\\"Deixe esse crep\xfasculo queimar!\\" \\nLaevatain \xe9 uma operadora da Rhodes Island que se juntou \xe0 Endfield por recomenda\xe7\xe3o direta do Endministrator. Segundo o acordo estrutural firmado entre as duas empresas, ela atua como operadora diretamente sob o comando do Endministrator. \\nAntes de ingressar na Endfield Industries, Laevatain vagava pelo mundo sozinha, perseguindo um objetivo que pudesse chamar de seu. Por causa dessa jornada e de sua formid\xe1vel habilidade em combate individual, as pessoas frequentemente a confundem com \\"algu\xe9m com quem voc\xea n\xe3o pode conversar\\". Na verdade, nada poderia estar mais longe da realidade. Acontece que sua natureza sincera e direta \xe0s vezes se imp\xf5e demais, dando origem a mal-entendidos. \\nEm algumas ocasi\xf5es, no entanto, ela fala de maneiras que confundem os outros, muitas vezes voltando ao assunto da \\"mem\xf3ria\\", como se estivesse propositalmente tentando se separar de quem ela \xe9. \\nEla frequentemente empunha chamas, mas tamb\xe9m anseia por sorvete. Para ela, talvez essa contradi\xe7\xe3o pare\xe7a perfeitamente natural. \\n\\n\\"Tente se aproximar de mim se ainda estiver com frio.\\"","prof":"assault","elem":"fire","cv":{"en-us":"Kira Buckland"}},{"key":"yvonne","name":"Yvonne","codename":"Yvonne","camp":"Endfield Industries","race":"Vouivre","rarity":6,"intro":"\\"Este par de canh\xf5es de m\xe3o parece perfeito. Humm... Percebi alguns erros de design. Acho que vou modific\xe1-los e transform\xe1-los em um par de especiais da Yvonne!\\" \\nYvonne \xe9 uma operadora na Divis\xe3o T\xe9cnica Especializada da Endfield Industries, onde \xe9 respons\xe1vel pelas pesquisas sobre \xc6ther, Praga e dispositivos relacionados. \\n\xc0 primeira vista, Yvonne parece a t\xedpica estilista rebelde — pintando seus chifres, cauda e unhas com cores chamativas. Ela \xe9 capaz de faltar a confer\xeancias acad\xeamicas s\xf3 para mergulhar nas \xfaltimas revistas de moda e \xe1lbuns pop. Atra\xedda por todas as coisas novas e n\xe3o convencionais, Yvonne tem um talento especial para ficar um passo \xe0 frente das tend\xeancias, sempre marchando no ritmo de seu pr\xf3prio tambor. \\nMas ningu\xe9m pode negar que ela \xe9 um verdadeiro g\xeanio. Mesmo em seus dias de escola, ela j\xe1 acumulava elogios em pesquisa cient\xedfica com os quais outros s\xf3 poderiam sonhar. Todos esperavam que ela se juntasse a um instituto de pesquisa de primeira linha e liderasse o movimento em seu campo. Em vez disso, Yvonne virou as costas para tudo e escolheu se juntar \xe0 Endfield. \\nO motivo? Ela nunca explicou. Talvez voc\xea possa perguntar diretamente a ela. \\n\\n\\"Posso aplicar uma nova camada de tinta no meu equipamento? Esse esquema de cores n\xe3o combina muito com o meu cabelo.\\"","prof":"assault","elem":"ice","cv":{"en-us":"Clare Louise Connolly"}},{"key":"gilberta","name":"Gilberta","codename":"Gilberta","camp":"Rhodes Island","race":"Vulpo","rarity":6,"intro":"\\"Ol\xe1! Ah, voc\xea tem o aroma rosado das belas lembran\xe7as... como uma carta incompleta destinada a um lugar especial. Imagino onde isso possa ser.\\" \\nGilberta \xe9 uma operadora da Rhodes Island designada para a Endfield Industries sob o acordo estrutural firmado entre as duas empresas. Ela atua como Mensageira na Divis\xe3o T\xe9cnica Especializada. Habilidosa em uma forma excepcionalmente rara de Artes de Originium, ela \xe9 capaz de controlar a gravidade ao seu redor. \\nNa Endfield, Gilberta \xe9 respons\xe1vel pela entrega de correspond\xeancias e informa\xe7\xf5es em v\xe1rias bases e postos avan\xe7ados. Suas tarefas frequentemente exigem que ela viaje pelas \xe1reas lim\xedtrofes entre o Cintur\xe3o da Civiliza\xe7\xe3o e a fronteira, mas ela parece realmente gostar do trabalho. Recentemente, ela at\xe9 come\xe7ou a pedir miss\xf5es mais desafiadoras em \xe1reas de alto risco para aprimorar suas habilidades. \\nWarfarin admitiu que a natureza otimista de Gilberta, aliada a uma pitada de inquieta\xe7\xe3o e esperan\xe7a pelo futuro, a deixou surpresa e um pouco nost\xe1lgica. \\n\\n\\"Olha s\xf3! A Senhorita Mensageira Voadora tem uma carta especial para voc\xea!\\"","prof":"support","elem":"nature","cv":{"en-us":"Anna Devlin"}},{"key":"ardelia","name":"Ardelia","codename":"Ardelia","camp":"Rhodes Island","race":"Caprinae","rarity":6,"intro":"\\"Este mundo tem tantos mist\xe9rios a serem desvendados. Dever\xedamos conhec\xea-lo melhor, assim como... assim como dever\xedamos aprender mais sobre n\xf3s mesmos. N\xe3o concorda, Professor?\\" \\nArdelia \xe9 uma operadora da Rhodes Island designada para a Endfield Industries, onde atua como ge\xf3loga especialista sob o acordo estrutural firmado entre as duas empresas. \\nNo in\xedcio, o trabalho de Ardelia se concentrava em vulc\xf5es, mas hoje sua pesquisa se estende ao \xc6therside e desastres geol\xf3gicos. Ela passa a maior parte do tempo em campo, aventurando-se sozinha em locais de desastres para coletar amostras, analisar estruturas e desenvolver teorias que se tornaram a pedra angular das contramedidas da Endfield para a Praga. \\nSempre humilde e educada, ela \xe9 dotada de uma for\xe7a interior que parece nunca se esgotar. Para ela, a felicidade \xe9 simples: escalar outra montanha, trilhar outro caminho, ouvir as vozes do mundo e descobrir as maravilhas ocultas deste planeta. \\nE se voc\xea conseguir se tornar um bom amigo de Ardelia, ent\xe3o o Sr. Dolly certamente gostar\xe1 de voc\xea tamb\xe9m. \\n\\n\\"Sr. Dolly? N\xe3o fuja! Venha cumprimentar o Professor.\\"","prof":"support","elem":"nature","cv":{"en-us":"Lindsay Sheppard"}},{"key":"ember","name":"Ember","codename":"Ember","camp":"Ordem do Juramento de A\xe7o","race":"Sankta","rarity":6,"intro":"\\"Vamos em frente. A guerra nunca acaba. S\xf3 nos resta marchar adiante.\\" \\nEmber serve na Ordem do Juramento de A\xe7o, uma for\xe7a militar estacionada o ano todo nas regi\xf5es acidentadas do norte. Para recrutar sucessores para seus companheiros ca\xeddos, ela retornou ao Cintur\xe3o da Civiliza\xe7\xe3o e aceitou um convite para trabalhar na Endfield Industries. \\nParte da elite do Estandarte de Assalto da Ordem do Juramento de A\xe7o, Ember luta com habilidades impec\xe1veis. Ela lidera cada investida, rompendo as linhas inimigas ao lado de seus companheiros como uma lan\xe7a inquebr\xe1vel. Para seus inimigos, ela \xe9 o baluarte que se mant\xe9m firme. Para seus aliados, ela \xe9 a muralha que nunca cai. A Ordem pode se sustentar em fortalezas e ve\xedculos de combate — mas guerreiros como Ember s\xe3o sua verdadeira espinha dorsal. \\n\\n\\"Sob a aurora, encontram-se as linhas de defesa dos Guardi\xf5es do Juramento.\\"","prof":"shielder","elem":"fire","cv":{"en-us":"Rhiannon Moushall"}},{"key":"lastrite","name":"Last Rite","codename":"Last Rite","camp":"Seš\'qa","race":"Sarkaz","rarity":6,"intro":"\\"Eu sou... algo da guerra, eu acho?\\" \\nAntes que os Sarkaz da cidade flutuante a encontrassem, Last Rite era uma garota bondosa adotada por um casal de coveiros Caprinae. Moldada por seus ensinamentos, a jovem Nachzehrer se recusava a perturbar os mortos, resistindo ao seu instinto de se alimentar. Mas essa conten\xe7\xe3o a deixava cambaleando de fome, e sua inseguran\xe7a a fazia se afastar dos outros. \\nUm encontro casual revelou o potencial de Last Rite para Seš\'qa. Seduzida pela promessa de \\"trabalho tempor\xe1rio bem remunerado\\" e \\"treinamento para suprimir instintos\\", ela passou a ser conhecida entre os mercadores como a Princesa da Corte de Guerra. Agora, vestida com um prot\xf3tipo de traje de combate da Witching Hour, ela empunha gelo e a\xe7o pela causa da Endfield — tanto para cumprir seu contrato quanto para lutar pelo futuro pac\xedfico que a Endfield tanto almeja. \\n\\n\\"Se meu contrato com Seš\'qa expirar, voc\xea pode entrar em contato comigo... Ah, n\xe3o! Eu n\xe3o deveria ter dito isso! Por favor... N\xe3o conte a ningu\xe9m sobre isso...\\"","prof":"assault","elem":"ice","cv":{"en-us":"Amber Hood"}},{"key":"lifeng","name":"Lifeng","codename":"Lifeng","camp":"Academia de Ci\xeancias de Hongshan","race":"Anasa","rarity":6,"intro":"\\"Vim para Endfield para aprender. Mas... tem muita coisa para absorver. Preciso me esfor\xe7ar ainda mais!\\" \\nLifeng, nascido na Cidade de Wuling, agora estagia na Divis\xe3o T\xe9cnica Especializada da Endfield Industries. \\nDe volta a Wuling, Lifeng \xe9 conhecido e amado como o l\xedder dos colegas. Anos de orienta\xe7\xe3o de Da Pan aprimoraram suas habilidades com lan\xe7as, preparando-o para sua busca por justi\xe7a. Poucos adivinhariam, por seu comportamento alegre, a sombra que ele carrega — um acidente que destruiu sua fam\xedlia outrora feliz e lhe custou um bra\xe7o. No entanto, as dificuldades nunca diminu\xedram sua chama. Ele continua a crescer com sinceridade e paix\xe3o, ansiando pelo dia em que poder\xe1 assumir responsabilidades maiores. Algum dia, ele se erguer\xe1 sozinho e retornar\xe1 para proteger o lar que o espera. \\n\\n\\"Um dia, serei capaz o suficiente para assumir as miss\xf5es mais dif\xedceis. Por favor, aguarde ansiosamente por esse dia, Endmin.\\"","prof":"guard","elem":"physic","cv":{"en-us":"Yung-I Chang"}},{"key":"pogranichnik","name":"Pogranichnik","codename":"Pogranichnik","camp":"Rhodes Island","race":"Liberi","rarity":6,"intro":"\\"A situa\xe7\xe3o \xe9 urgente. Solicito respeitosamente um resumo do seu plano de batalha, o mais breve poss\xedvel.\\" \\nPogranichnik \xe9 um operador da Rhodes Island designado para a Endfield Industries, onde atua como consultor militar sob o acordo estrutural firmado entre as duas empresas. \\nCom profundo conhecimento da teoria militar e experi\xeancia arduamente conquistada em combate em equipe, Pogranichnik lidera sua unidade at\xe9 mesmo nas crises mais inesperadas. Outrora comandante do Estandarte dos Escudeiros na Ordem do Juramento de A\xe7o, ele e suas tropas passaram a ser considerados uns dos mais confi\xe1veis na linha de frente contra os Aggeloi. Mas, \xe0 medida que a situa\xe7\xe3o em Talos-II se tornava cada vez mais complexa, ele se juntou \xe0 Endfield Industries sem hesitar. \\nEle acredita piamente que o Endministrator conduzir\xe1 a Talos-II por um novo caminho, exatamente como ele havia imaginado. \\n\\n\\"Endmin, n\xe3o tenho d\xfavidas de que suas a\xe7\xf5es por\xe3o um fim solene a este ciclo cruel de guerra e sacrif\xedcio.\\"","prof":"vanguard","elem":"physic","cv":{"en-us":"Sergey Ponomaryov"}},{"key":"alesh","name":"Alesh","codename":"Alesh","camp":"Sindicatos dos Trabalhadores Unidos de Talos-II","race":"Anaty","rarity":5,"intro":"\\"Voc\xea sempre pode recuperar uma isca quando est\xe1 pescando. Mas, na vida real, n\xe3o h\xe1 sa\xedda f\xe1cil quando se est\xe1 em apuros.\\" \\nApresentado por um contato do Departamento de Seguran\xe7a do STUT, Alesh se juntou \xe0 Endfield Industries para assumir as comunica\xe7\xf5es e cobrir tarefas na fronteira. Quando n\xe3o est\xe1 trabalhando, ele tamb\xe9m \xe9 instrutor em aulas de pesca na Endfield. \\nEle n\xe3o gosta de falar sobre seu passado \\"chato\\". Tudo o que se sabe \xe9 que ele se arrastou entre as classes baixas da fronteira, aguentando conflitos e trai\xe7\xf5es o tempo inteiro. No final, ele deixou as ruas para tr\xe1s com um olho cego e um corpo desgastado pela exaust\xe3o. \\nA profiss\xe3o de Alesh \xe9 vendedor de barbatanas, o que o faz passar os dias absorto na pesca. Mas por tr\xe1s dessa superf\xedcie descontra\xedda escondem-se instintos agu\xe7ados e julgamento apurado. Em apuros, seus olhos cortam como a ponta de um anzol, e ele tem tantos truques para lidar com problemas quanto para fisgar uma presa. Em miss\xf5es, ele ostenta o mesmo sorriso f\xe1cil, conquistando vit\xf3rias onde ningu\xe9m espera. \\n\\n\\"Viver uma vida feliz \xe9 importante. A verdadeira sabedoria de um velho garoto, Endmin\\".","prof":"vanguard","elem":"ice","cv":{"en-us":"Heitor Assali"}},{"key":"arclight","name":"Arclight","codename":"Arclight","camp":"Circuito Hannabit","race":"Kuranta","rarity":5,"intro":"\\"Eu sou Ekut. Meu codinome \xe9 Arclight. N\xe3o sou muito boa com palavras, mas desejo a voc\xeas tudo de bom e que voc\xeas fluam como um rio caudaloso, Endfielders.\\" \\nArclight \xe9 uma Ca\xe7adora de M\xfasicas que se juntou \xe0 Endfield Industries por recomenda\xe7\xe3o de Aldertone Orisha. Ela agora atua como operadora de campo e consultora t\xe9cnica para m\xe1quinas e ve\xedculos. \\nNingu\xe9m que vagasse pelas terras selvagens conseguia escapar das garras da fome e dos desastres, por mais inteligente ou capaz que se achasse. O infort\xfanio atingiu Arclight com for\xe7a. As terras selvagens consumiram toda a sua fam\xedlia, deixando-a como a \xfanica sobrevivente. No entanto, a sorte tamb\xe9m lhe sorriu quando um grupo de Ca\xe7adores de M\xfasicas do Circuito Hannabit a encontrou e salvou da beira da morte. \\nO Circuito Hannabit a aceitou. L\xe1, ela aprendeu rapidamente a sobreviver em um cen\xe1rio hostil e a seguir o exemplo dos Paragons de Hannas para ajudar os necessitados. Hoje, ela vaga pelas terras selvagens para ensinar a mais almas o caminho da sobreviv\xeancia no mundo implac\xe1vel de Talos-II. \\nArclight pode parecer fria e brusca no come\xe7o, mas sua filosofia minimalista provou ser excepcionalmente eficaz para sobreviver nas terras selvagens. \\n\\n\\"Consertar um corcel de ferro \xe9 como tratar uma besta c\xedstica. \xc9 preciso ouvir atentamente antes de aplicar o tratamento.\\"","prof":"vanguard","elem":"electric","cv":{"en-us":"Andrea Gatchalian"}},{"key":"avywenna","name":"Avywenna","codename":"Avywenna","camp":"C\xe2mara Geral de Com\xe9rcio de Talos-II","race":"Cautus","rarity":5,"intro":"\\"Os mensageiros precisam entregar muitos segredos com seguran\xe7a, e cada um deles tem um pre\xe7o alto. Mas h\xe1 algo mais caro do que a entrega em si... o meu sil\xeancio sobre esses assuntos.\\" \\nAvywenna \xe9 uma Mensageira Armada. \\nAntes de ingressar na Endfield Industries, ela morava com uma poderosa fam\xedlia de log\xedstica na Cidade Livre de Alloycarrot. No entanto, a sede de viajar em seu sangue a levou a abandonar essa vida e come\xe7ar sua pr\xf3pria jornada. Atrav\xe9s dos muitos destinos de Talos-II, ela descobriu um fio condutor que os unia — o misterioso Endministrator. \\nAvywenna brilha em ambientes sociais, lidando com todos os tipos de relacionamentos com maturidade e profissionalismo. Se ela \xe9 realmente t\xe3o bem-humorada quanto parece, voc\xea ter\xe1 que descobrir conversando com ela pessoalmente. \\n\\n\\"Ningu\xe9m gosta de insol\xeancia... ent\xe3o, se pudermos conversar, prefiro muito mais fazer isso do que brigar. Mas, para deixar claro, eu tamb\xe9m n\xe3o tolero insol\xeancia.\\"","prof":"assault","elem":"electric","cv":{"en-us":"Sheena May"}},{"key":"dapan","name":"Da Pan","codename":"Da Pan","camp":"Academia de Ci\xeancias de Hongshan","race":"Ursus","rarity":5,"intro":"\\"Se voc\xea n\xe3o \xe9 bom com um prato, fa\xe7a-o com mais frequ\xeancia! Eu n\xe3o cozinho para me exibir! Cozinho para fazer um banquete bonito e alegre!\\" \\nDa Pan vem da prestigiosa Academia de Ci\xeancias de Hongshan, mas, ap\xf3s sair, desempenhou todos os tipos de \\"fun\xe7\xf5es essenciais de apoio log\xedstico dispersas\\" — de chef e eletricista a motorista e vendedor ambulante. Sua \xfaltima mudan\xe7a? Ingressar na Divis\xe3o T\xe9cnica Especializada da Endfield Industries como aut\xf4nomo. \\nDe todas as fun\xe7\xf5es que assumiu, a que mais se orgulha \xe9 a de chef viajante. Ele \xe9 apaixonado por explorar novas receitas e criar pratos criativos. Nada o deixa mais feliz do que elaborar refei\xe7\xf5es deliciosas que recebem elogios de todos os clientes que serve. \\nDa Pan carrega uma garrafa de \xe1gua o tempo todo, embora poucos a notem. Aqueles que conseguem ler caracteres yaneses podem se perguntar sobre sua origem. Mas, se forem de Hongshan, saber\xe3o exatamente de onde ela veio e o peso que ela carrega como uma honra concedida apenas a um Cientista de Vanguarda. \\n\\n\\"Experimente isso. Eu mesmo preparei!\\"","prof":"assault","elem":"physic","cv":{"en-us":"Jon Xu"}},{"key":"snowshine","name":"Snowshine","codename":"Snowshine","camp":"Rhodes Island","race":"Ursus","rarity":5,"intro":"\\"A velocidade do vento est\xe1 OK. A visibilidade \xe9 boa. Clima perfeito para snowboarding.\\" \\nSnowshine \xe9 uma operadora da Rhodes Island designada para a Endfield Industries, onde atua como profissional de busca e resgate (BER) sob o acordo estrutural firmado entre as duas empresas. \\nPor raz\xf5es bem conhecidas, as verdadeiras regi\xf5es polares de Talos-II permanecem inacess\xedveis \xe0 humanidade. No entanto, com a retomada da expans\xe3o da fronteira, profissionais como Snowshine, especializados na geografia de regi\xf5es polares e de alta altitude, est\xe3o em crescente demanda dentro do Cintur\xe3o da Civiliza\xe7\xe3o. \\nDevido \xe0 grande escassez de talentos, Snowshine e sua equipe de resgate est\xe3o sempre com a agenda lotada, mesmo em dias sem miss\xf5es especiais. \\nApesar da agenda lotada, ela conseguiu escrever um livro intitulado Guia da Sobreviv\xeancia Polar em seu tempo livre. Desde ent\xe3o, o livro se tornou uma refer\xeancia fundamental para opera\xe7\xf5es de sobreviv\xeancia e BER nos ambientes hostis e nevados de Talos-II. \\n\\n\\"Gosto da neve, das montanhas com picos brancos e da beleza cintilante que s\xf3 se revela no frio glacial... \xc9 por isso que n\xe3o quero que as pessoas voltem para casa com lembran\xe7as dolorosas.\\"","prof":"shielder","elem":"ice","cv":{"en-us":"Stephanie Southerland"}},{"key":"wulfgard","name":"Wulfgard","codename":"Wulfgard","camp":"Endfield Industries","race":"Lupo","rarity":5,"intro":"\\"Eu sei que for\xe7a n\xe3o \xe9 tudo, mas em Talos-II, n\xe3o se vive sem ela.\\" \\nCatello Wulfgard Luppino \xe9 um jovem mercen\xe1rio que vive nas margens do Cintur\xe3o da Civiliza\xe7\xe3o e agora atua na Equipe de Crises da Endfield Industries. \\nApesar de jovem, Wulfgard j\xe1 conhece bem a natureza mais inconstante da humanidade. Mas, em vez de destru\xed-lo, essas experi\xeancias proporcionaram a ele uma maturidade muito al\xe9m de sua idade. Ele n\xe3o busca conflitos e, em caso de d\xfavida, prefere evitar o confronto direto. Ele tamb\xe9m \xe9 habilidoso em opera\xe7\xf5es de combate furtivas e de reconhecimento. Para completar sua miss\xe3o, o mercen\xe1rio pode at\xe9 viajar com seus inimigos e desferir o golpe letal quando eles menos esperam. \\nMembro do cl\xe3 Invasor de Terras conhecido como a Matilha, Wulfgard poder\xe1 ser um amigo fiel se voc\xea conseguir conquistar sua confian\xe7a. Mas isso n\xe3o \xe9 tarefa f\xe1cil. \\n\\n\\"O idealismo irrealista destr\xf3i mais vidas do que salva.\\"","prof":"caster","elem":"fire","cv":{"en-us":"Jacopo Calatroni"}},{"key":"xaihi","name":"Xaihi","codename":"Xaihi","camp":"Cabala da Tranquilidade","race":"Sarkaz","rarity":5,"intro":"\\"Quando estivermos conectadas, a sabedoria brotar\xe1.\\" \\nXaihi faz parte da Cabala da Tranquilidade, uma ordem de pesquisa enviada de Laterano para Talos-II para estudos t\xe9cnicos. Como uma Sessionita, ela acredita que a computa\xe7\xe3o e a an\xe1lise lingu\xedstica pavimentam o caminho para a Veritas. \\nEla \xe9 melhor com m\xe1quinas do que com pessoas. Seu talento em tecnologia da informa\xe7\xe3o \xe9 ineg\xe1vel — at\xe9 mesmo para a Abadessa do Grande Monast\xe9rio da Cabala da Tranquilidade. Portanto, apesar de sua modifica\xe7\xe3o \\"n\xe3o autorizada\\" na c\xfapula da Catedralis ter desencadeado uma s\xe9rie de acidentes, a Abadessa ainda a recomendou de forma sincera para a Endfield Industries, esperando que ela pudesse encontrar um palco digno de sua genialidade. \\nAgora, Xaihi trabalha a bordo da Dijiang em tarefas de engenharia da informa\xe7\xe3o, como a constru\xe7\xe3o da Rede de Protorig e integra\xe7\xe3o de sistemas. Seus insights \xfanicos sobre a Rede de Originium, combinados com o profundo conhecimento que ela carrega da Cabala, garantem seu lugar como membro indispens\xe1vel da Endfield. \\n\\n\\"\xd3 Conhecimento mais antigo, n\xe3o nos deixes cair em tenta\xe7\xe3o, mas livra-nos dos c\xf3digos da mal\xedcia... Eu sou Xaihi, Endministrator. Que sejas iluminado.\\"","prof":"support","elem":"ice","cv":{"en-us":"Elsie Lovelock"}},{"key":"akekuri","name":"Akekuri","codename":"Akekuri","camp":"Endfield Industries","race":"Perro","rarity":4,"intro":"\\"Akekuri, Op Z7, se apresentando! Estou muito empolgada para participar da miss\xe3o, vamos torn\xe1-la um sucesso!\\" \\nAkekuri, Capit\xe3 da Equipe de Opera\xe7\xf5es Z7 da Divis\xe3o T\xe9cnica Especializada, \xe9 conhecida por seu sorriso e por sua frase caracter\xedstica: \\"Deixe comigo\\". Do planejamento da miss\xe3o \xe0 gest\xe3o di\xe1ria, ela cuida de tudo. Al\xe9m do comando t\xe1tico e da estrat\xe9gia, ela \xe9 mestra em coordena\xe7\xe3o e sempre encontra a solu\xe7\xe3o ideal, mesmo com recursos limitados. Ela tamb\xe9m sabe cuidar de sua equipe, garantindo que todos trabalhem em harmonia e se destaquem na fun\xe7\xe3o que melhor lhes conv\xe9m. \\nEla praticamente construiu a Equipe de Opera\xe7\xf5es Z7 do zero. Em apenas alguns meses, cuidou de tudo, do recrutamento e treinamento \xe0 mobiliza\xe7\xe3o completa, levando a equipe a resultados not\xe1veis. E pensar que, h\xe1 pouco tempo, ela era apenas uma aluna exemplar da Escola de Neg\xf3cios que se voluntariou para se juntar \xe0 Endfield. Ningu\xe9m esperava que uma rec\xe9m-chegada ascendesse t\xe3o rapidamente e se tornasse uma capit\xe3 verdadeiramente confi\xe1vel. \\nSe voc\xea j\xe1 se perguntou sobre sua paix\xe3o, sua determina\xe7\xe3o e seu idealismo, ou sobre o simples desejo que a mant\xe9m seguindo em frente, ent\xe3o... \\n\\n\\"Que tal uma pausa para o caf\xe9, Endmin? Posso preparar um bule fresquinho para voc\xea!\\"","prof":"vanguard","elem":"fire","cv":{"en-us":"Shu Uchida"}},{"key":"antal","name":"Antal","codename":"Antal","camp":"Endfield Industries","race":"Savra","rarity":4,"intro":"\\"Uma miss\xe3o para mim? \xd3timo. Estou buscando oportunidades de testes de campo para drones orbitais modificados.\\" \\nMembro da Equipe de Opera\xe7\xf5es Z7 na Endfield, Antal trabalha como apoiador e consultor de tecnologia de Originium. Ele \xe9 inteligente e r\xe1pido na compreens\xe3o, mas n\xe3o \xe9 o melhor em ler as pessoas. Mais de uma vez, ele fez coment\xe1rios t\xe3o fora de prop\xf3sito que deixou o resto da equipe reclamando. Mesmo assim, seu talento para as Artes de Originium \xe9 not\xe1vel, embora ele pr\xf3prio pare\xe7a n\xe3o saber disso. \\nInfluenciado por sua av\xf3, Antal n\xe3o se importa muito com o sucesso convencional e concentra toda a sua aten\xe7\xe3o em tudo o que o fascina. Seja um dispositivo de Originium que ele nunca viu antes ou uma piada seca que o deixa maravilhado, este jovem Savra n\xe3o descansar\xe1 por dias at\xe9 sentir que desvendou seus segredos. \\n\\n\\"Curiosamente, sua presen\xe7a amplia muito minha vontade de compartilhar meu vasto conhecimento.\\"","prof":"support","elem":"electric","cv":{"en-us":"Jacob Craner"}},{"key":"catcher","name":"Catcher","codename":"Catcher","camp":"Endfield Industries","race":"Perro","rarity":4,"intro":"\\"Precisa de cobertura defensiva? Vou te dar o meu melhor.\\" \\nCatcher serve na Equipe de Opera\xe7\xf5es Z7 da Endfield, onde \xe9 respons\xe1vel pela cobertura e pelo apoio log\xedstico. Tendo recebido treinamento militar completo, ele usa seu vasto conhecimento para guiar seus companheiros de equipe em momentos cr\xedticos. Nascido em uma fam\xedlia militar dentro da C\xe2mara Geral de Com\xe9rcio de Talos-II, ele foi criado com o amor de pais dedicados e irm\xe3os mais velhos. A dor e a doen\xe7a causadas por um acidente de inf\xe2ncia nunca o derrubaram. Em vez disso, elas moldaram o guerreiro inabal\xe1vel que ele \xe9 hoje. \\nCatcher pode ser o mais jovem da equipe, mas sua maturidade supera em muito a de seus colegas. Ele pode trabalhar perfeitamente com todos, prontamente cobrir quando um companheiro de equipe enfrenta dificuldades e at\xe9 mesmo preparar uma refei\xe7\xe3o de acampamento sob medida para as necessidades de todos. Com ele por perto, a equipe sempre se sente segura e \xe0 vontade. \\n\\n\\"Recentemente, revisei as sugest\xf5es de todos e melhorei minha receita de ensopado das terras selvagens... Sinta-se \xe0 vontade para experimentar se estiver curioso, Endmin.\\"","prof":"shielder","elem":"physic","cv":{"en-us":"Kevin Andrew Rivera"}},{"key":"estella","name":"Estella","codename":"Estella","camp":"Endfield Industries","race":"Felino","rarity":4,"intro":"\\"Hngh... Parece que o peso do mundo inteiro caiu sobre mim... meus joelhos, especialmente...\\" \\nMembro da Equipe de Opera\xe7\xf5es Z7 na Endfield, Estella cuida da coleta de informa\xe7\xf5es e das comunica\xe7\xf5es. Fisicamente fraca e cercada de infort\xfanios por onde passa, \xe0s vezes deixa sua l\xedngua afiada e seu humor \xe1cido afastarem quem n\xe3o a conhece. Seu sonho \xe9 simples: viver uma vida pac\xedfica. Afinal, ela j\xe1 viu muitas pessoas como ela, presas em um mundo sem escolhas, sem mudan\xe7as e sem futuro. \\nUma vida de perigos e extremos entorpeceu seus sentidos para o mundo e elevou seu limiar de est\xedmulo. Como resultado, ela \xe0s vezes busca formas mais duras de desafio — como a onda pulsante do heavy metal. Esses raros sobressaltos d\xe3o a ela uma sensa\xe7\xe3o fugaz de mudan\xe7a e algo real. \\nPor meio de seu trabalho na Endfield, Estella espera tornar o mundo um pouco melhor e a vida um pouco mais f\xe1cil para aqueles ao seu redor. \\n\\n\\"Eu me esforcei demais de novo... Hngh... \xc9 melhor aproveitar a pausa enquanto ela dura.\\"","prof":"guard","elem":"ice","cv":{"en-us":"Risa Mei"}},{"key":"fluorite","name":"Fluorite","codename":"Fluorite","camp":"Endfield Industries","race":"Phidia","rarity":4,"intro":"\\"Distra\xed-los? Desabilit\xe1-los? Ou... simplesmente destru\xed-los?\\" \\nMembro da Equipe de Opera\xe7\xf5es Z7 na Endfield, Fluorite \xe9 respons\xe1vel por patrulhar e romper as linhas inimigas. Seu dom\xednio das regras de rua e truques sujos rivaliza com sua pontaria, poupando a equipe de in\xfameros problemas. Vinda da fronteira nos limites do Cintur\xe3o da Civiliza\xe7\xe3o, ela agu\xe7ou seu olhar atrav\xe9s de constantes migra\xe7\xf5es e perambula\xe7\xf5es. Na maioria das vezes, ela simplesmente se senta no canto com um sorriso fraco, deixando os outros com a sensa\xe7\xe3o inquietante de que cada falha j\xe1 foi exposta sob seu olhar. \\nMas n\xe3o a confunda com uma pessoa emp\xe1tica. O talento de Fluorite para ler as pessoas d\xe1 a ela instintos excepcionais no campo de batalha, mas tamb\xe9m a torna perigosamente boa em provocar as pessoas com apenas algumas palavras — tornando-a a fonte de problemas mais imprevis\xedvel da equipe. \\n\\n\\"Tem algo a dizer? N\xe3o? Que tal encerrarmos o dia?\\"","prof":"caster","elem":"nature","cv":{"en-us":"Katiana Sarkissian"}}]'),h={SansMedium:'\n        url("'.concat(n(10414),'") format("woff2"),\n        url("').concat(n(84726),'") format("woff"),\n        url("').concat(n(20544),'") format("truetype"),\n    '),SansBold:'\n        url("'.concat(n(74738),'") format("woff2"),\n        url("').concat(n(33922),'") format("woff"),\n        url("').concat(n(29804),'") format("truetype"),\n    '),SansBlack:'\n        url("'.concat(n(30610),'") format("woff2"),\n        url("').concat(n(33058),'") format("woff"),\n        url("').concat(n(7404),'") format("truetype"),\n    '),SansRegular:'\n        url("'.concat(n(89095),'") format("woff2"),\n        url("').concat(n(90149),'") format("woff"),\n        url("').concat(n(2085),'") format("truetype"),\n    ')},p=JSON.parse('{"aic.items.0.description":"O poderoso Complexo Automatizado Industrial (CAI) da Endfield Industries permite a produ\xe7\xe3o automatizada eficiente de v\xe1rios equipamentos, explosivos, baterias, itens t\xe1ticos e outros materiais.","aic.items.0.title":"Produ\xe7\xe3o Automatizada","aic.items.1.description":"O N\xfacleo de Automa\xe7\xe3o do Protocolo (NAP) \xe9 uma das principais conquistas tecnol\xf3gicas da Endfield. Utilizando o Teleprotocolo, o NAP pode \\"imprimir\\" toda uma variedade de instala\xe7\xf5es e estender as tecnologias do CAI a todos os cantos de Talos-II.","aic.items.1.title":"N\xfacleo de Automa\xe7\xe3o do Protocolo","aic.items.2.description":"A Endfield Industries utiliza unidades de log\xedstica poderosas, como esteiras de transporte, Divisores e o Transportador do Dep\xf3sito. Essas unidades s\xe3o essenciais para a cria\xe7\xe3o r\xe1pida de linhas de produ\xe7\xe3o automatizadas.","aic.items.2.title":"Sistema de Log\xedstica","aic.items.3.description":"A Endfield Industries utiliza Torres de Transmiss\xe3o e Postes de Eletricidade para distribuir eletricidade do NAP para as instala\xe7\xf5es conectadas. Isso mant\xe9m a energia fluindo e as instala\xe7\xf5es funcionando para a produ\xe7\xe3o automatizada.","aic.items.3.title":"Sistema de Energia","aic.items.4.description":"A F\xe1brica do CAI em Wuling apresenta novas instala\xe7\xf5es de coleta e processamento de v\xe1rios fluidos, permitindo a produ\xe7\xe3o em massa de um material not\xe1vel conhecido como Xiranita. Uma vez instalados, os Rel\xe9s de Xiranita e os Postes de Xiranita, desenvolvidos pela Academia de Ci\xeancias de Hongshan, se conectar\xe3o automaticamente \xe0 rede el\xe9trica existente e fornecer\xe3o eletricidade \xe0s instala\xe7\xf5es pr\xf3ximas.","aic.items.4.title":"Plano do CAI de Wuling","common.back":"Voltar","common.latest":"Mais recentes","common.selectLanguage":"Selecionar idioma","gameplay.items.0.description":"Aventure-se pelas imponentes cordilheiras e pelos rios sinuosos de Talos-II. Elimine a Praga e neutralize as amea\xe7as de Ankhor. Lidere a Endfield Industries na expans\xe3o pelo planeta enquanto constr\xf3i e desenvolve cada regi\xe3o ao longo do caminho.","gameplay.items.0.title":"Explore Talos-II","gameplay.items.1.description":"Lidere sua equipe na batalha, trabalhando em sincronia e usando combos de habilidades para derrotar todos os tipos de inimigos. Unam-se para proteger nosso lar Talos-II.","gameplay.items.1.title":"Combate em Equipe","gameplay.items.2.description":"Use diversas instala\xe7\xf5es da Endfield para construir linhas de produ\xe7\xe3o automatizadas. Siga os projetos ou construa livremente para produzir de tudo, desde equipamentos e explosivos at\xe9 alimentos e medicamentos, para apoiaa expans\xe3o cont\xednua.","gameplay.items.2.title":"Construa a F\xe1brica do CAI","gameplay.items.3.description":"Mantenha a sede da Endfield Industries funcionando suavemente. Construa e fa\xe7a o upgrade de diversas cabines, interaja com os operadores para estabelecer confian\xe7a, exiba suas conquistas na Sala da Recep\xe7\xe3o e receba convidados ou visite outras pessoas.","gameplay.items.3.title":"Gerencie a Endfield Industries","header.charge":"Centro de Recargas","header.creator":"Criadores","header.login":"Fazer login","header.mute.off":"Som: Ligado","header.mute.on":"Som: Desligado","header.user":"Conta","home.activity":"Carga Total!","home.actPreGacha":"Pr\xe9-sorteio","home.download":"Download","home.fillQuestionnaire":"Beta Sign-Up","home.questionnaireDisabled":"Pesquisa enviada","home.reserve":"Pr\xe9-inscri\xe7\xe3o","home.themeSite":"Galeria tem\xe1tica","home.title":"No Despertar \\nda Primavera","home.title.v1d4":"Volta Para Casa","home.title1.v1d4":"Vers\xe3o do Cap\xedtulo Principal","home.title2.v1d4":"Batalha em Wuling","home.title3.v1d4":"Juntos Novamente, Um Novo Cap\xedtulo Come\xe7a","information.cate.CHARACTER":"Exibi\xe7\xe3o de Personagens","information.cate.SPECIAL":"Trailer Especial","information.cate.VERSION":"Trailer da Vers\xe3o","information.displayTimeFormat":"DD/MM/YYYY","information.more":"Mais v\xeddeos","landing.downloadNow":"Baixe agora","landing.frontInfo":"OVER THE FRONTIER / INTO THE FRONT","landing.gameDesc":"3D即时策略RPG游戏","landing.welcome":"Nova vers\xe3o chegando","lore.models.anchor.codename":"ANKHOR","lore.models.anchor.intro":"Ankhors s\xe3o constru\xe7\xf5es misteriosas que desencadeiam a forma\xe7\xe3o de Aggeloi. Suas origens permanecem desconhecidas e est\xe3o espalhadas aleatoriamente por Talos-II. Assim que pousam, come\xe7am a extrair materiais naturais pr\xf3ximos para criar Aggeloi continuamente.","lore.models.anchor.name":"Ankhor","lore.models.enemy.codename":"LANDBREAKER","lore.models.enemy.intro":"O termo Invasores de Terras geralmente se refere a grupos de invasores armados nas periferias da sociedade que ganham a vida com roubos ou outras formas de viol\xeancia criminosa. Quando os sonhos de conquista dos Invasores de Terras foram destru\xeddos, a gangue se dividiu em v\xe1rias ramifica\xe7\xf5es. Cada uma agora tem um nome diferente, mas as pessoas ainda usam \\"Invasores de Terras\\" como um termo gen\xe9rico para qualquer grupo armado que se oponha \xe0 ordem civilizada.","lore.models.enemy.name":"Invasor de Terras","lore.models.factory.codename":"AIC","lore.models.factory.intro":"O Complexo Automatizado Industrial (CAI) \xe9 uma das principais tecnologias da Endfield Industries.  Ele representa a miniaturiza\xe7\xe3o e modulariza\xe7\xe3o bem-sucedidas de m\xe1quinas de produ\xe7\xe3o industrial. Uma pequena equipe de profissionais equipada com a tecnologia do CAI pode implementar rapidamente uma linha de produ\xe7\xe3o automatizada totalmente funcional.","lore.models.factory.name":"Complexo Automatizado Industrial","lore.models.pile.codename":"TIANSHI PILLAR","lore.models.pile.intro":"Os Pilares de Tianshi s\xe3o dispositivos de Xiranita em forma de coluna desenvolvidos para combater a Mar\xe9 de Praga. Eles se destacam como uma das maiores conquistas cient\xedficas da Academia de Ci\xeancias de Hongshan. Ao combinarem tecnologia de Originium com estudos de Feranmut, Tianshi da ACH inventaram o Pilar de Tianshi para combater a Mar\xe9 de Praga. O dispositivo dispersa part\xedculas de Xiranita e as ativa conforme necess\xe1rio para enfraquecer os efeitos da Praga.","lore.models.pile.name":"Pilar de Tianshi","lore.models.spaceship.codename":"DIJIANG","lore.models.spaceship.intro":"A NMO Dijiang \xe9 uma nave espacial em \xf3rbita geoestacion\xe1ria artificial acima de Talos-II. \xc9 a atual sede da Endfield Industries.  Alimentada por um gigantesco n\xfacleo de Protocolo-Originium, ela sustenta v\xe1rios subsistemas, entre eles o Teleprotocolo (TP) e o Complexo Automatizado Industrial (CAI).","lore.models.spaceship.name":"Dijiang","lore.models.trinity.codename":"AGGELOID","lore.models.trinity.intro":"Aggelos (plural: Aggeloi) refere-se a qualquer entidade hostil e animada composta de mat\xe9ria natural e uma estrutura de aur\xe9ola, e \xe9 criada por um Ankhor por meio de constru\xe7\xe3o catal\xedtica. Ao longo da hist\xf3ria da expans\xe3o da humanidade por Talos-II, os Aggeloi sempre foram nossa principal amea\xe7a. A Guerra dos Aggeloi recebeu o nome do inimigo combatido pela humanidade.","lore.models.trinity.name":"Aggelos","modal.user.currentUser":"Conta atual","modal.user.logout":"Logout","modal.user.title":"Informa\xe7\xf5es da Conta","modal.user.userCenter":"Central de Contas","nav.aic":"Introdu\xe7\xe3o \xe0 F\xe1brica do CAI","nav.calendar":"Calend\xe1rio da vers\xe3o","nav.gameplay":"Jogabilidade","nav.home":"In\xedcio","nav.information":"M\xeddia","nav.lore":"Hist\xf3ria","nav.milestone":"Metas de Pr\xe9-Inscri\xe7\xe3o","nav.notice":"Novidades","nav.operator":"Operadores","nav.preserveNow":"Fa\xe7a sua pr\xe9-inscri\xe7\xe3o agora","nav.preserveNowShort":"Pr\xe9-inscri\xe7\xe3o","notice.detail":"Mais Informa\xe7\xf5es","notice.tab.events":"Eventos","notice.tab.news":"Novidades","notice.tab.notices":"Avisos","operator.camp":"Fac\xe7\xe3o","operator.camps.0":"Endfield Industries","operator.camps.1":"Circuito Hannabit","operator.camps.2":"Ordem do Juramento de A\xe7o","operator.camps.3":"Cabala da Tranquilidade","operator.camps.4":"C\xe2mara Geral de Com\xe9rcio de Talos-II","operator.camps.5":"Rhodes Island","operator.camps.6":"Academia de Ci\xeancias de Hongshan","operator.camps.7":"Sindicatos dos Trabalhadores Unidos de Talos-II","operator.camps.8":"Seš\'qa","operator.content.akekuri.intro":"\\"Akekuri, Op Z7, se apresentando! Estou muito empolgada para participar da miss\xe3o, vamos torn\xe1-la um sucesso!\\"  Akekuri, Capit\xe3 da Equipe de Opera\xe7\xf5es Z7 da Divis\xe3o T\xe9cnica Especializada, \xe9 conhecida por seu sorriso e por sua frase caracter\xedstica: \\"Deixe comigo\\". Do planejamento da miss\xe3o \xe0 gest\xe3o di\xe1ria, ela cuida de tudo. Al\xe9m do comando t\xe1tico e da estrat\xe9gia, ela \xe9 mestra em coordena\xe7\xe3o e sempre encontra a solu\xe7\xe3o ideal, mesmo com recursos limitados. Ela tamb\xe9m sabe cuidar de sua equipe, garantindo que todos trabalhem em harmonia e se destaquem na fun\xe7\xe3o que melhor lhes conv\xe9m.  Ela praticamente construiu a Equipe de Opera\xe7\xf5es Z7 do zero. Em apenas alguns meses, cuidou de tudo, do recrutamento e treinamento \xe0 mobiliza\xe7\xe3o completa, levando a equipe a resultados not\xe1veis. E pensar que, h\xe1 pouco tempo, ela era apenas uma aluna exemplar da Escola de Neg\xf3cios que se voluntariou para se juntar \xe0 Endfield. Ningu\xe9m esperava que uma rec\xe9m-chegada ascendesse t\xe3o rapidamente e se tornasse uma capit\xe3 verdadeiramente confi\xe1vel.  Se voc\xea j\xe1 se perguntou sobre sua paix\xe3o, sua determina\xe7\xe3o e seu idealismo, ou sobre o simples desejo que a mant\xe9m seguindo em frente, ent\xe3o...  \\n \\"Que tal uma pausa para o caf\xe9, Endmin? Posso preparar um bule fresquinho para voc\xea!\\"","operator.content.akekuri.name":"Akekuri","operator.content.alesh.intro":"\\"Voc\xea sempre pode recuperar uma isca quando est\xe1 pescando. Mas, na vida real, n\xe3o h\xe1 sa\xedda f\xe1cil quando se est\xe1 em apuros.\\"  Apresentado por um contato do Departamento de Seguran\xe7a do STUT, Alesh se juntou \xe0 Endfield Industries para assumir as comunica\xe7\xf5es e cobrir tarefas na fronteira. Quando n\xe3o est\xe1 trabalhando, ele tamb\xe9m \xe9 instrutor em aulas de pesca na Endfield.  Ele n\xe3o gosta de falar sobre seu passado \\"chato\\". Tudo o que se sabe \xe9 que ele se arrastou entre as classes baixas da fronteira, aguentando conflitos e trai\xe7\xf5es o tempo inteiro. No final, ele deixou as ruas para tr\xe1s com um olho cego e um corpo desgastado pela exaust\xe3o.  A profiss\xe3o de Alesh \xe9 vendedor de barbatanas, o que o faz passar os dias absorto na pesca. Mas por tr\xe1s dessa superf\xedcie descontra\xedda escondem-se instintos agu\xe7ados e julgamento apurado. Em apuros, seus olhos cortam como a ponta de um anzol, e ele tem tantos truques para lidar com problemas quanto para fisgar uma presa. Em miss\xf5es, ele ostenta o mesmo sorriso f\xe1cil, conquistando vit\xf3rias onde ningu\xe9m espera.  \\n \\"Viver uma vida feliz \xe9 importante. A verdadeira sabedoria de um velho garoto, Endmin\\".","operator.content.alesh.name":"Alesh","operator.content.antal.intro":"\\"Uma miss\xe3o para mim? \xd3timo. Estou buscando oportunidades de testes de campo para drones orbitais modificados.\\"  Membro da Equipe de Opera\xe7\xf5es Z7 na Endfield, Antal trabalha como apoiador e consultor de tecnologia de Originium. Ele \xe9 inteligente e r\xe1pido na compreens\xe3o, mas n\xe3o \xe9 o melhor em ler as pessoas. Mais de uma vez, ele fez coment\xe1rios t\xe3o fora de prop\xf3sito que deixou o resto da equipe reclamando. Mesmo assim, seu talento para as Artes de Originium \xe9 not\xe1vel, embora ele pr\xf3prio pare\xe7a n\xe3o saber disso.  Influenciado por sua av\xf3, Antal n\xe3o se importa muito com o sucesso convencional e concentra toda a sua aten\xe7\xe3o em tudo o que o fascina. Seja um dispositivo de Originium que ele nunca viu antes ou uma piada seca que o deixa maravilhado, este jovem Savra n\xe3o descansar\xe1 por dias at\xe9 sentir que desvendou seus segredos.  \\n \\"Curiosamente, sua presen\xe7a amplia muito minha vontade de compartilhar meu vasto conhecimento.\\"","operator.content.antal.name":"Antal","operator.content.arclight.intro":"\\"Eu sou Ekut. Meu codinome \xe9 Arclight. N\xe3o sou muito boa com palavras, mas desejo a voc\xeas tudo de bom e que voc\xeas fluam como um rio caudaloso, Endfielders.\\"  Arclight \xe9 uma Ca\xe7adora de M\xfasicas que se juntou \xe0 Endfield Industries por recomenda\xe7\xe3o de Aldertone Orisha. Ela agora atua como operadora de campo e consultora t\xe9cnica para m\xe1quinas e ve\xedculos.  Ningu\xe9m que vagasse pelas terras selvagens conseguia escapar das garras da fome e dos desastres, por mais inteligente ou capaz que se achasse. O infort\xfanio atingiu Arclight com for\xe7a. As terras selvagens consumiram toda a sua fam\xedlia, deixando-a como a \xfanica sobrevivente. No entanto, a sorte tamb\xe9m lhe sorriu quando um grupo de Ca\xe7adores de M\xfasicas do Circuito Hannabit a encontrou e salvou da beira da morte.  O Circuito Hannabit a aceitou. L\xe1, ela aprendeu rapidamente a sobreviver em um cen\xe1rio hostil e a seguir o exemplo dos Paragons de Hannas para ajudar os necessitados. Hoje, ela vaga pelas terras selvagens para ensinar a mais almas o caminho da sobreviv\xeancia no mundo implac\xe1vel de Talos-II.  Arclight pode parecer fria e brusca no come\xe7o, mas sua filosofia minimalista provou ser excepcionalmente eficaz para sobreviver nas terras selvagens.  \\n \\"Consertar um corcel de ferro \xe9 como tratar uma besta c\xedstica. \xc9 preciso ouvir atentamente antes de aplicar o tratamento.\\"","operator.content.arclight.name":"Arclight","operator.content.ardelia.intro":"\\"Este mundo tem tantos mist\xe9rios a serem desvendados. Dever\xedamos conhec\xea-lo melhor, assim como... assim como dever\xedamos aprender mais sobre n\xf3s mesmos. N\xe3o concorda, Professor?\\"  Ardelia \xe9 uma operadora da Rhodes Island designada para a Endfield Industries, onde atua como ge\xf3loga especialista sob o acordo estrutural firmado entre as duas empresas.  No in\xedcio, o trabalho de Ardelia se concentrava em vulc\xf5es, mas hoje sua pesquisa se estende ao \xc6therside e desastres geol\xf3gicos. Ela passa a maior parte do tempo em campo, aventurando-se sozinha em locais de desastres para coletar amostras, analisar estruturas e desenvolver teorias que se tornaram a pedra angular das contramedidas da Endfield para a Praga.  Sempre humilde e educada, ela \xe9 dotada de uma for\xe7a interior que parece nunca se esgotar. Para ela, a felicidade \xe9 simples: escalar outra montanha, trilhar outro caminho, ouvir as vozes do mundo e descobrir as maravilhas ocultas deste planeta.  E se voc\xea conseguir se tornar um bom amigo de Ardelia, ent\xe3o o Sr. Dolly certamente gostar\xe1 de voc\xea tamb\xe9m.  \\n \\"Sr. Dolly? N\xe3o fuja! Venha cumprimentar o Professor.\\"","operator.content.ardelia.name":"Ardelia","operator.content.avywenna.intro":"\\"Os mensageiros precisam entregar muitos segredos com seguran\xe7a, e cada um deles tem um pre\xe7o alto. Mas h\xe1 algo mais caro do que a entrega em si... o meu sil\xeancio sobre esses assuntos.\\"  Avywenna \xe9 uma Mensageira Armada.  Antes de ingressar na Endfield Industries, ela morava com uma poderosa fam\xedlia de log\xedstica na Cidade Livre de Alloycarrot. No entanto, a sede de viajar em seu sangue a levou a abandonar essa vida e come\xe7ar sua pr\xf3pria jornada. Atrav\xe9s dos muitos destinos de Talos-II, ela descobriu um fio condutor que os unia — o misterioso Endministrator.  Avywenna brilha em ambientes sociais, lidando com todos os tipos de relacionamentos com maturidade e profissionalismo. Se ela \xe9 realmente t\xe3o bem-humorada quanto parece, voc\xea ter\xe1 que descobrir conversando com ela pessoalmente.  \\n \\"Ningu\xe9m gosta de insol\xeancia... ent\xe3o, se pudermos conversar, prefiro muito mais fazer isso do que brigar. Mas, para deixar claro, eu tamb\xe9m n\xe3o tolero insol\xeancia.\\"","operator.content.avywenna.name":"Avywenna","operator.content.catcher.intro":"\\"Precisa de cobertura defensiva? Vou te dar o meu melhor.\\"  Catcher serve na Equipe de Opera\xe7\xf5es Z7 da Endfield, onde \xe9 respons\xe1vel pela cobertura e pelo apoio log\xedstico. Tendo recebido treinamento militar completo, ele usa seu vasto conhecimento para guiar seus companheiros de equipe em momentos cr\xedticos. Nascido em uma fam\xedlia militar dentro da C\xe2mara Geral de Com\xe9rcio de Talos-II, ele foi criado com o amor de pais dedicados e irm\xe3os mais velhos. A dor e a doen\xe7a causadas por um acidente de inf\xe2ncia nunca o derrubaram. Em vez disso, elas moldaram o guerreiro inabal\xe1vel que ele \xe9 hoje.  Catcher pode ser o mais jovem da equipe, mas sua maturidade supera em muito a de seus colegas. Ele pode trabalhar perfeitamente com todos, prontamente cobrir quando um companheiro de equipe enfrenta dificuldades e at\xe9 mesmo preparar uma refei\xe7\xe3o de acampamento sob medida para as necessidades de todos. Com ele por perto, a equipe sempre se sente segura e \xe0 vontade.  \\n \\"Recentemente, revisei as sugest\xf5es de todos e melhorei minha receita de ensopado das terras selvagens... Sinta-se \xe0 vontade para experimentar se estiver curioso, Endmin.\\"","operator.content.catcher.name":"Catcher","operator.content.chen.intro":"\\"Pois \xe9, descobri que sou \xf3tima em outras coisas al\xe9m de artes marciais. \xc9 imposs\xedvel n\xe3o acabar sendo a sua melhor operadora.\\"  Chen Qianyu \xe9 operadora na Endfield Industries e membro essencial da Equipe de Crises.  Desde jovem, treinou artes marciais sob a orienta\xe7\xe3o de sua m\xe3e e no Tanjian Hall. Sua dedica\xe7\xe3o rendeu a ela excelentes habilidades de combate e uma fortaleza mental raramente vista entre seus pares. Embora nunca tenha visto a lend\xe1ria Chi Xiao, ela orgulhosamente mant\xe9m seu Dom\xednio da Espada Chi Xiao, desenvolvido por si mesma, e a empunha em nome da justi\xe7a.  Depois de anos vagando por Talos-II sozinha com sua espada, Chen Qianyu se juntou \xe0 Endfield a convite de Perlica. Sua natureza otimista e seu entusiasmo feroz a levam a encarar todos os desafios urgentes sem hesita\xe7\xe3o.  \\n \\"Dizem que a l\xe2mina da minha m\xe3e agitou as pr\xf3prias nuvens, Endmin. E eu farei exatamente isso... e me tornarei aquela com quem voc\xea e Perlica sempre poder\xe3o contar!\\"","operator.content.chen.name":"Chen Qianyu","operator.content.dapan.intro":"\\"Se voc\xea n\xe3o \xe9 bom com um prato, fa\xe7a-o com mais frequ\xeancia! Eu n\xe3o cozinho para me exibir! Cozinho para fazer um banquete bonito e alegre!\\"  Da Pan vem da prestigiosa Academia de Ci\xeancias de Hongshan, mas, ap\xf3s sair, desempenhou todos os tipos de \\"fun\xe7\xf5es essenciais de apoio log\xedstico dispersas\\" — de chef e eletricista a motorista e vendedor ambulante. Sua \xfaltima mudan\xe7a? Ingressar na Divis\xe3o T\xe9cnica Especializada da Endfield Industries como aut\xf4nomo.  De todas as fun\xe7\xf5es que assumiu, a que mais se orgulha \xe9 a de chef viajante. Ele \xe9 apaixonado por explorar novas receitas e criar pratos criativos. Nada o deixa mais feliz do que elaborar refei\xe7\xf5es deliciosas que recebem elogios de todos os clientes que serve.  Da Pan carrega uma garrafa de \xe1gua o tempo todo, embora poucos a notem. Aqueles que conseguem ler caracteres yaneses podem se perguntar sobre sua origem. Mas, se forem de Hongshan, saber\xe3o exatamente de onde ela veio e o peso que ela carrega como uma honra concedida apenas a um Cientista de Vanguarda.  \\n \\"Experimente isso. Eu mesmo preparei!\\"","operator.content.dapan.name":"Da Pan","operator.content.ember.intro":"\\"Vamos em frente. A guerra nunca acaba. S\xf3 nos resta marchar adiante.\\"  Ember serve na Ordem do Juramento de A\xe7o, uma for\xe7a militar estacionada o ano todo nas regi\xf5es acidentadas do norte. Para recrutar sucessores para seus companheiros ca\xeddos, ela retornou ao Cintur\xe3o da Civiliza\xe7\xe3o e aceitou um convite para trabalhar na Endfield Industries.  Parte da elite do Estandarte de Assalto da Ordem do Juramento de A\xe7o, Ember luta com habilidades impec\xe1veis. Ela lidera cada investida, rompendo as linhas inimigas ao lado de seus companheiros como uma lan\xe7a inquebr\xe1vel. Para seus inimigos, ela \xe9 o baluarte que se mant\xe9m firme. Para seus aliados, ela \xe9 a muralha que nunca cai. A Ordem pode se sustentar em fortalezas e ve\xedculos de combate — mas guerreiros como Ember s\xe3o sua verdadeira espinha dorsal.  \\n \\"Sob a aurora, encontram-se as linhas de defesa dos Guardi\xf5es do Juramento.\\"","operator.content.ember.name":"Ember","operator.content.endministrator1.intro":"O Endministrator da Endfield Industries. Na hist\xf3ria registrada de Talos-II, o Endministrator \xe9 um guardi\xe3o fundamental que protegeu a civiliza\xe7\xe3o neste planeta e salvou a humanidade de in\xfameros desastres catastr\xf3ficos. Os feitos heroicos de Endmin deram origem a muitas hist\xf3rias, contos e at\xe9 rumores.  No entanto, a identidade de Endmin permanece desconhecida e apenas algumas pessoas j\xe1 tiveram a oportunidade de conhecer a lenda pessoalmente.  Outras fac\xe7\xf5es dentro do Cintur\xe3o da Civiliza\xe7\xe3o sabem muito bem que a Endfield tem um trunfo muito especial em m\xe3os, mas isso \xe9 tudo o que sabem.  O misterioso dom\xednio do Endministrator sobre o Originium e a Rede do Protocolo, juntamente com a necessidade de hibernar periodicamente por longos per\xedodos, \xe9 um dos segredos mais importantes da Endfield.","operator.content.endministrator1.name":"Endministrator","operator.content.endministrator2.intro":"O Endministrator da Endfield Industries. Na hist\xf3ria registrada de Talos-II, o Endministrator \xe9 um guardi\xe3o fundamental que protegeu a civiliza\xe7\xe3o neste planeta e salvou a humanidade de in\xfameros desastres catastr\xf3ficos. Os feitos heroicos de Endmin deram origem a muitas hist\xf3rias, contos e at\xe9 rumores.  No entanto, a identidade de Endmin permanece desconhecida e apenas algumas pessoas j\xe1 tiveram a oportunidade de conhecer a lenda pessoalmente.  Outras fac\xe7\xf5es dentro do Cintur\xe3o da Civiliza\xe7\xe3o sabem muito bem que a Endfield tem um trunfo muito especial em m\xe3os, mas isso \xe9 tudo o que sabem.  O misterioso dom\xednio do Endministrator sobre o Originium e a Rede do Protocolo, juntamente com a necessidade de hibernar periodicamente por longos per\xedodos, \xe9 um dos segredos mais importantes da Endfield.","operator.content.endministrator2.name":"Endministrator","operator.content.estella.intro":"\\"Hngh... Parece que o peso do mundo inteiro caiu sobre mim... meus joelhos, especialmente...\\"  Membro da Equipe de Opera\xe7\xf5es Z7 na Endfield, Estella cuida da coleta de informa\xe7\xf5es e das comunica\xe7\xf5es. Fisicamente fraca e cercada de infort\xfanios por onde passa, \xe0s vezes deixa sua l\xedngua afiada e seu humor \xe1cido afastarem quem n\xe3o a conhece. Seu sonho \xe9 simples: viver uma vida pac\xedfica. Afinal, ela j\xe1 viu muitas pessoas como ela, presas em um mundo sem escolhas, sem mudan\xe7as e sem futuro.  Uma vida de perigos e extremos entorpeceu seus sentidos para o mundo e elevou seu limiar de est\xedmulo. Como resultado, ela \xe0s vezes busca formas mais duras de desafio — como a onda pulsante do heavy metal. Esses raros sobressaltos d\xe3o a ela uma sensa\xe7\xe3o fugaz de mudan\xe7a e algo real.  Por meio de seu trabalho na Endfield, Estella espera tornar o mundo um pouco melhor e a vida um pouco mais f\xe1cil para aqueles ao seu redor.  \\n \\"Eu me esforcei demais de novo... Hngh... \xc9 melhor aproveitar a pausa enquanto ela dura.\\"","operator.content.estella.name":"Estella","operator.content.fluorite.intro":"\\"Distra\xed-los? Desabilit\xe1-los? Ou... simplesmente destru\xed-los?\\"  Membro da Equipe de Opera\xe7\xf5es Z7 na Endfield, Fluorite \xe9 respons\xe1vel por patrulhar e romper as linhas inimigas. Seu dom\xednio das regras de rua e truques sujos rivaliza com sua pontaria, poupando a equipe de in\xfameros problemas. Vinda da fronteira nos limites do Cintur\xe3o da Civiliza\xe7\xe3o, ela agu\xe7ou seu olhar atrav\xe9s de constantes migra\xe7\xf5es e perambula\xe7\xf5es. Na maioria das vezes, ela simplesmente se senta no canto com um sorriso fraco, deixando os outros com a sensa\xe7\xe3o inquietante de que cada falha j\xe1 foi exposta sob seu olhar.  Mas n\xe3o a confunda com uma pessoa emp\xe1tica. O talento de Fluorite para ler as pessoas d\xe1 a ela instintos excepcionais no campo de batalha, mas tamb\xe9m a torna perigosamente boa em provocar as pessoas com apenas algumas palavras — tornando-a a fonte de problemas mais imprevis\xedvel da equipe.  \\n \\"Tem algo a dizer? N\xe3o? Que tal encerrarmos o dia?\\"","operator.content.fluorite.name":"Fluorite","operator.content.gilberta.intro":"\\"Ol\xe1! Ah, voc\xea tem o aroma rosado das belas lembran\xe7as... como uma carta incompleta destinada a um lugar especial. Imagino onde isso possa ser.\\"  Gilberta \xe9 uma operadora da Rhodes Island designada para a Endfield Industries sob o acordo estrutural firmado entre as duas empresas. Ela atua como Mensageira na Divis\xe3o T\xe9cnica Especializada. Habilidosa em uma forma excepcionalmente rara de Artes de Originium, ela \xe9 capaz de controlar a gravidade ao seu redor.  Na Endfield, Gilberta \xe9 respons\xe1vel pela entrega de correspond\xeancias e informa\xe7\xf5es em v\xe1rias bases e postos avan\xe7ados. Suas tarefas frequentemente exigem que ela viaje pelas \xe1reas lim\xedtrofes entre o Cintur\xe3o da Civiliza\xe7\xe3o e a fronteira, mas ela parece realmente gostar do trabalho. Recentemente, ela at\xe9 come\xe7ou a pedir miss\xf5es mais desafiadoras em \xe1reas de alto risco para aprimorar suas habilidades.  Warfarin admitiu que a natureza otimista de Gilberta, aliada a uma pitada de inquieta\xe7\xe3o e esperan\xe7a pelo futuro, a deixou surpresa e um pouco nost\xe1lgica.  \\n \\"Olha s\xf3! A Senhorita Mensageira Voadora tem uma carta especial para voc\xea!\\"","operator.content.gilberta.name":"Gilberta","operator.content.laevatain.intro":"\\"Deixe esse crep\xfasculo queimar!\\"  Laevatain \xe9 uma operadora da Rhodes Island que se juntou \xe0 Endfield por recomenda\xe7\xe3o direta do Endministrator. Segundo o acordo estrutural firmado entre as duas empresas, ela atua como operadora diretamente sob o comando do Endministrator.  Antes de ingressar na Endfield Industries, Laevatain vagava pelo mundo sozinha, perseguindo um objetivo que pudesse chamar de seu. Por causa dessa jornada e de sua formid\xe1vel habilidade em combate individual, as pessoas frequentemente a confundem com \\"algu\xe9m com quem voc\xea n\xe3o pode conversar\\". Na verdade, nada poderia estar mais longe da realidade. Acontece que sua natureza sincera e direta \xe0s vezes se imp\xf5e demais, dando origem a mal-entendidos.  Em algumas ocasi\xf5es, no entanto, ela fala de maneiras que confundem os outros, muitas vezes voltando ao assunto da \\"mem\xf3ria\\", como se estivesse propositalmente tentando se separar de quem ela \xe9.  Ela frequentemente empunha chamas, mas tamb\xe9m anseia por sorvete. Para ela, talvez essa contradi\xe7\xe3o pare\xe7a perfeitamente natural.  \\n \\"Tente se aproximar de mim se ainda estiver com frio.\\"","operator.content.laevatain.name":"Laevatain","operator.content.lastrite.intro":"\\"Eu sou... algo da guerra, eu acho?\\"  Antes que os Sarkaz da cidade flutuante a encontrassem, Last Rite era uma garota bondosa adotada por um casal de coveiros Caprinae. Moldada por seus ensinamentos, a jovem Nachzehrer se recusava a perturbar os mortos, resistindo ao seu instinto de se alimentar. Mas essa conten\xe7\xe3o a deixava cambaleando de fome, e sua inseguran\xe7a a fazia se afastar dos outros.  Um encontro casual revelou o potencial de Last Rite para Seš\'qa. Seduzida pela promessa de \\"trabalho tempor\xe1rio bem remunerado\\" e \\"treinamento para suprimir instintos\\", ela passou a ser conhecida entre os mercadores como a Princesa da Corte de Guerra. Agora, vestida com um prot\xf3tipo de traje de combate da Witching Hour, ela empunha gelo e a\xe7o pela causa da Endfield — tanto para cumprir seu contrato quanto para lutar pelo futuro pac\xedfico que a Endfield tanto almeja.  \\n \\"Se meu contrato com Seš\'qa expirar, voc\xea pode entrar em contato comigo... Ah, n\xe3o! Eu n\xe3o deveria ter dito isso! Por favor... N\xe3o conte a ningu\xe9m sobre isso...\\"","operator.content.lastrite.name":"Last Rite","operator.content.lifeng.intro":"\\"Vim para Endfield para aprender. Mas... tem muita coisa para absorver. Preciso me esfor\xe7ar ainda mais!\\"  Lifeng, nascido na Cidade de Wuling, agora estagia na Divis\xe3o T\xe9cnica Especializada da Endfield Industries.  De volta a Wuling, Lifeng \xe9 conhecido e amado como o l\xedder dos colegas. Anos de orienta\xe7\xe3o de Da Pan aprimoraram suas habilidades com lan\xe7as, preparando-o para sua busca por justi\xe7a. Poucos adivinhariam, por seu comportamento alegre, a sombra que ele carrega — um acidente que destruiu sua fam\xedlia outrora feliz e lhe custou um bra\xe7o. No entanto, as dificuldades nunca diminu\xedram sua chama. Ele continua a crescer com sinceridade e paix\xe3o, ansiando pelo dia em que poder\xe1 assumir responsabilidades maiores. Algum dia, ele se erguer\xe1 sozinho e retornar\xe1 para proteger o lar que o espera.  \\n \\"Um dia, serei capaz o suficiente para assumir as miss\xf5es mais dif\xedceis. Por favor, aguarde ansiosamente por esse dia, Endmin.\\"","operator.content.lifeng.name":"Lifeng","operator.content.perlica.intro":"\\"Lutamos e nunca desistimos... pois \xe9 nosso desejo testemunhar o seu retorno.\\"  Perlica \xe9 a Supervisora da Endfield Industries e porta-voz oficial da empresa. Ela \xe9 a principal respons\xe1vel por supervisionar e promover o desenvolvimento e a aplica\xe7\xe3o da tecnologia de Protocolo-Originium, al\xe9m de gerenciar as opera\xe7\xf5es da Dijiang.  Como especialista excepcional em Tecnoprotocolo, ela orientou pesquisas que tiveram uma influ\xeancia fundamental no desenvolvimento adaptativo e na aplica\xe7\xe3o da tecnologia e ajudou a refinar o Complexo Automatizado Industrial (F\xe1brica do CAI).  Ela \xe9 capaz de responder a diversas crises com calma e decis\xe3o. No entanto, a Endfield frequentemente enfrenta desafios que v\xe3o al\xe9m de todas as expectativas. Enquanto o Endministrator permanecia em hiberna\xe7\xe3o, ela assumiu o comando da Equipe de Crises, liderando os her\xf3is da Endfield Industries em uma batalha por uma causa maior. Perlica se move incansavelmente pelo Cintur\xe3o da Civiliza\xe7\xe3o, fazendo tudo o que pode para manter a ordem e manter as coisas funcionando.  \\n \\"Somente caminhando sobre a terra podemos realmente apreciar cada respira\xe7\xe3o e pulsa\xe7\xe3o da vida... E \xe9 por isso que a Endfield est\xe1 lutando.\\"","operator.content.perlica.name":"Perlica","operator.content.pogranichnik.intro":"\\"A situa\xe7\xe3o \xe9 urgente. Solicito respeitosamente um resumo do seu plano de batalha, o mais breve poss\xedvel.\\"  Pogranichnik \xe9 um operador da Rhodes Island designado para a Endfield Industries, onde atua como consultor militar sob o acordo estrutural firmado entre as duas empresas.  Com profundo conhecimento da teoria militar e experi\xeancia arduamente conquistada em combate em equipe, Pogranichnik lidera sua unidade at\xe9 mesmo nas crises mais inesperadas. Outrora comandante do Estandarte dos Escudeiros na Ordem do Juramento de A\xe7o, ele e suas tropas passaram a ser considerados uns dos mais confi\xe1veis na linha de frente contra os Aggeloi. Mas, \xe0 medida que a situa\xe7\xe3o em Talos-II se tornava cada vez mais complexa, ele se juntou \xe0 Endfield Industries sem hesitar.  Ele acredita piamente que o Endministrator conduzir\xe1 a Talos-II por um novo caminho, exatamente como ele havia imaginado.  \\n \\"Endmin, n\xe3o tenho d\xfavidas de que suas a\xe7\xf5es por\xe3o um fim solene a este ciclo cruel de guerra e sacrif\xedcio.\\"","operator.content.pogranichnik.name":"Pogranichnik","operator.content.rossi.intro":"\\"Moleza para algu\xe9m da elite como eu!\\"  Rossina Wulfperl Luppino, irm\xe3 mais nova de Wulfgard e a P\xe9rola da Matilha. Em um feudo entre a Matilha e os Quebra-Ossos, muitos lobos anci\xe3os pagaram um pre\xe7o muito alto para resgat\xe1-la. O sangue daquele dia manchou de vermelho o cobertor em que ela estava enrolada...  Wulfgard opera independentemente do cl\xe3 por anos, mas a Matilha precisava de um l\xedder, e Rossi aceitou essa responsabilidade. Ela sempre sentiu que seu irm\xe3o, que ascendeu \xe0 fama ainda jovem, deveria ser o l\xedder de toda a Matilha, e constantemente o lembra e o incentiva a faz\xea-lo. Embora os anci\xe3os do cl\xe3 esperem que Rossi possa passar mais tempo fazendo o que ama em sua idade, ela, no fim das contas, n\xe3o consegue se livrar do peso da \\"responsabilidade\\". Ela se esfor\xe7a para se tornar mais confi\xe1vel e poderosa pelo bem de sua fam\xedlia e do cl\xe3.  Rossi, que anseia por hist\xf3rias heroicas, ocasionalmente fantasia que um dia poder\xe1 lutar ao lado de um her\xf3i lend\xe1rio. Este \xe9 o seu momento de \\"tempo para si mesma\\".  \\"Eles mordem muito fundo, mas a Matilha n\xe3o tem medo de mais cicatrizes!\\"","operator.content.rossi.name":"Rossi","operator.content.snowshine.intro":"\\"A velocidade do vento est\xe1 OK. A visibilidade \xe9 boa. Clima perfeito para snowboarding.\\"  Snowshine \xe9 uma operadora da Rhodes Island designada para a Endfield Industries, onde atua como profissional de busca e resgate (BER) sob o acordo estrutural firmado entre as duas empresas.  Por raz\xf5es bem conhecidas, as verdadeiras regi\xf5es polares de Talos-II permanecem inacess\xedveis \xe0 humanidade. No entanto, com a retomada da expans\xe3o da fronteira, profissionais como Snowshine, especializados na geografia de regi\xf5es polares e de alta altitude, est\xe3o em crescente demanda dentro do Cintur\xe3o da Civiliza\xe7\xe3o.  Devido \xe0 grande escassez de talentos, Snowshine e sua equipe de resgate est\xe3o sempre com a agenda lotada, mesmo em dias sem miss\xf5es especiais.  Apesar da agenda lotada, ela conseguiu escrever um livro intitulado Guia da Sobreviv\xeancia Polar em seu tempo livre. Desde ent\xe3o, o livro se tornou uma refer\xeancia fundamental para opera\xe7\xf5es de sobreviv\xeancia e BER nos ambientes hostis e nevados de Talos-II.  \\n \\"Gosto da neve, das montanhas com picos brancos e da beleza cintilante que s\xf3 se revela no frio glacial... \xc9 por isso que n\xe3o quero que as pessoas voltem para casa com lembran\xe7as dolorosas.\\"","operator.content.snowshine.name":"Snowshine","operator.content.tangtang.intro":"\\"Sua Chefe Suprema est\xe1 aqui! Voc\xea, voc\xea e voc\xea est\xe3o todos sob meu comando!\\"  Tangtang, a Chefe Suprema da Pali\xe7ada de Qingbo. Ela \xe9 direta, valoriza a lealdade e age com um esp\xedrito livre e desinibido. Ama a liberdade e brincar na \xe1gua, mas detesta trai\xe7\xe3o. Uma vez que reconhe\xe7a voc\xea como amigo, far\xe1 de tudo para ajudar.  Ainda beb\xea, Tangtang foi colocada em uma cesta de bambu por um desconhecido e levada pela correnteza do rio at\xe9 a Pali\xe7ada de Qingbo, onde foi adotada pelos Pali\xe7ados e se tornou uma deles. Aos olhos de muitos, ela ainda \xe9 uma crian\xe7a que precisa de carinho, mas em seu cora\xe7\xe3o, ela j\xe1 decidiu h\xe1 muito tempo contribuir para o futuro da Pali\xe7ada de Qingbo.  Mesmo tendo enfrentado muitos contratempos, permanece apaixonada pelo mundo. Para encontrar respostas para suas perguntas e contribuir para o desenvolvimento da Pali\xe7ada de Qingbo, Tangtang se juntou \xe0 Endfield Industries.  \\"Mantenha-a longe de Mi Fu, ou as coisas podem quebrar\\" — disse um operador do Escrit\xf3rio de Log\xedstica Principal.  \\"Voc\xea me chamou s\xf3 para me elogiar? Ent\xe3o, n\xe3o economize nos elogios. Adoro ouvir a verdade!\\"","operator.content.tangtang.name":"Tangtang","operator.content.wulfgard.intro":"\\"Eu sei que for\xe7a n\xe3o \xe9 tudo, mas em Talos-II, n\xe3o se vive sem ela.\\"  Catello Wulfgard Luppino \xe9 um jovem mercen\xe1rio que vive nas margens do Cintur\xe3o da Civiliza\xe7\xe3o e agora atua na Equipe de Crises da Endfield Industries.  Apesar de jovem, Wulfgard j\xe1 conhece bem a natureza mais inconstante da humanidade. Mas, em vez de destru\xed-lo, essas experi\xeancias proporcionaram a ele uma maturidade muito al\xe9m de sua idade. Ele n\xe3o busca conflitos e, em caso de d\xfavida, prefere evitar o confronto direto. Ele tamb\xe9m \xe9 habilidoso em opera\xe7\xf5es de combate furtivas e de reconhecimento. Para completar sua miss\xe3o, o mercen\xe1rio pode at\xe9 viajar com seus inimigos e desferir o golpe letal quando eles menos esperam.  Membro do cl\xe3 Invasor de Terras conhecido como a Matilha, Wulfgard poder\xe1 ser um amigo fiel se voc\xea conseguir conquistar sua confian\xe7a. Mas isso n\xe3o \xe9 tarefa f\xe1cil.  \\n \\"O idealismo irrealista destr\xf3i mais vidas do que salva.\\"","operator.content.wulfgard.name":"Wulfgard","operator.content.xaihi.intro":"\\"Quando estivermos conectadas, a sabedoria brotar\xe1.\\"  Xaihi faz parte da Cabala da Tranquilidade, uma ordem de pesquisa enviada de Laterano para Talos-II para estudos t\xe9cnicos. Como uma Sessionita, ela acredita que a computa\xe7\xe3o e a an\xe1lise lingu\xedstica pavimentam o caminho para a Veritas.  Ela \xe9 melhor com m\xe1quinas do que com pessoas. Seu talento em tecnologia da informa\xe7\xe3o \xe9 ineg\xe1vel — at\xe9 mesmo para a Abadessa do Grande Monast\xe9rio da Cabala da Tranquilidade. Portanto, apesar de sua modifica\xe7\xe3o \\"n\xe3o autorizada\\" na c\xfapula da Catedralis ter desencadeado uma s\xe9rie de acidentes, a Abadessa ainda a recomendou de forma sincera para a Endfield Industries, esperando que ela pudesse encontrar um palco digno de sua genialidade.  Agora, Xaihi trabalha a bordo da Dijiang em tarefas de engenharia da informa\xe7\xe3o, como a constru\xe7\xe3o da Rede de Protorig e integra\xe7\xe3o de sistemas. Seus insights \xfanicos sobre a Rede de Originium, combinados com o profundo conhecimento que ela carrega da Cabala, garantem seu lugar como membro indispens\xe1vel da Endfield.  \\n \\"\xd3 Conhecimento mais antigo, n\xe3o nos deixes cair em tenta\xe7\xe3o, mas livra-nos dos c\xf3digos da mal\xedcia... Eu sou Xaihi, Endministrator. Que sejas iluminado.\\"","operator.content.xaihi.name":"Xaihi","operator.content.yvonne.intro":"\\"Este par de canh\xf5es de m\xe3o parece perfeito. Humm... Percebi alguns erros de design. Acho que vou modific\xe1-los e transform\xe1-los em um par de especiais da Yvonne!\\"  Yvonne \xe9 uma operadora na Divis\xe3o T\xe9cnica Especializada da Endfield Industries, onde \xe9 respons\xe1vel pelas pesquisas sobre \xc6ther, Praga e dispositivos relacionados.  \xc0 primeira vista, Yvonne parece a t\xedpica estilista rebelde — pintando seus chifres, cauda e unhas com cores chamativas. Ela \xe9 capaz de faltar a confer\xeancias acad\xeamicas s\xf3 para mergulhar nas \xfaltimas revistas de moda e \xe1lbuns pop. Atra\xedda por todas as coisas novas e n\xe3o convencionais, Yvonne tem um talento especial para ficar um passo \xe0 frente das tend\xeancias, sempre marchando no ritmo de seu pr\xf3prio tambor.  Mas ningu\xe9m pode negar que ela \xe9 um verdadeiro g\xeanio. Mesmo em seus dias de escola, ela j\xe1 acumulava elogios em pesquisa cient\xedfica com os quais outros s\xf3 poderiam sonhar. Todos esperavam que ela se juntasse a um instituto de pesquisa de primeira linha e liderasse o movimento em seu campo. Em vez disso, Yvonne virou as costas para tudo e escolheu se juntar \xe0 Endfield.  O motivo? Ela nunca explicou. Talvez voc\xea possa perguntar diretamente a ela.  \\n \\"Posso aplicar uma nova camada de tinta no meu equipamento? Esse esquema de cores n\xe3o combina muito com o meu cabelo.\\"","operator.content.yvonne.name":"Yvonne","operator.detail.back":"Voltar para Lista de Operadores","operator.elem.electric":"El\xe9trico","operator.elem.fire":"T\xe9rmico","operator.elem.ice":"Crio","operator.elem.nature":"Natureza","operator.elem.physic":"F\xedsico","operator.filter.all":"Todos","operator.filter.elem":"Elemento","operator.filter.prof":"Classe","operator.more":"Todos os Operadores","operator.prof.assault":"Atacante","operator.prof.caster":"Conjurador","operator.prof.guard":"Guarda","operator.prof.shielder":"Defensor","operator.prof.support":"Apoiador","operator.prof.vanguard":"Vanguarda","operator.race":"Ra\xe7a","operator.races.0":"N\xe3o divulgado","operator.races.1":"Anasa","operator.races.10":"Caprinae","operator.races.11":"Cautus","operator.races.12":"Savra","operator.races.13":"Sankta","operator.races.14":"Sarkaz","operator.races.15":"Vouivre","operator.races.16":"Vulpo","operator.races.17":"Ursus","operator.races.18":"Kylin","operator.races.2":"Anaty","operator.races.3":"Phidia","operator.races.4":"Felino","operator.races.5":"Kuranta","operator.races.6":"Liberi","operator.races.7":"Lung","operator.races.8":"Lupo","operator.races.9":"Perro","reserveFooter.title":"Fa\xe7a sua pr\xe9-inscri\xe7\xe3o agora","reserveFooter.titleReserved":"Pr\xe9-inscri\xe7\xe3o conclu\xedda","reserveFooter.titleReserved2":"Boas-vindas a Talos-II","section.aic":"Introdu\xe7\xe3o \xe0 F\xe1brica do CAI","section.gameplay":"Jogabilidade","section.information":"M\xeddia","section.lore":"Hist\xf3ria","section.milestone":"Metas de Pr\xe9-Inscri\xe7\xe3o Globais da Endfield","section.notice":"Novidades","subpage.news.empty":"Nenhum conte\xfado ainda","subpage.news.title":"Novidades","subpage.video.empty":"Nenhum conte\xfado ainda","subpage.video.title":"V\xeddeos","toast.networkError":"Erro de rede","operator.content.zhuangfy.name":"Zhuang Fangyi","operator.content.zhuangfy.intro":"\\"Se voc\xea nunca desistir, nunca perder\xe1 de verdade.\\" \\nA operadora Zhuang Fangyi atua como Vice-Rainha do Distrito de Desenvolvimento Cient\xedfico de Wuling e tamb\xe9m como Tianshi respons\xe1vel pelo Projeto de Novos Materiais \xe0 Base de Xiranita. Por recomenda\xe7\xe3o da ACH, ela se juntou \xe0 Endfield Industries para conduzir pesquisas relacionadas \xe0 fenda. \\nZhuang Fangyi, natural de Hongshan, demonstrou aptid\xe3o extraordin\xe1ria desde cedo e foi admitida nas Academias do Escrit\xf3rio Tianshi antes de atingir a idade adulta, tendo apresentado desempenho acad\xeamico excepcional. Posteriormente, foi selecionada para o Projeto Xiranita devido \xe0s suas habilidades excepcionais, tornando-se a membro mais jovem da Esta\xe7\xe3o Cient\xedfica de Wuling. Ap\xf3s um desastre que resultou na perda quase total de pessoal na Esta\xe7\xe3o Cient\xedfica, ela, apesar de ser a membro mais jovem, foi nomeada para o cargo de Vice-Rainha, assumindo responsabilidades de lideran\xe7a e carregando o peso de toda Wuling. \\nNomeada em um momento de crise, ela rapidamente se reergueu. Em apenas uma d\xe9cada, ela n\xe3o s\xf3 transformou Wuling em uma cidade pr\xf3spera, como tamb\xe9m, por meio de tentativas e erros, tornou-se uma l\xedder dedicada e respons\xe1vel. No entanto, o desastre de uma d\xe9cada atr\xe1s continua sendo uma espada pendendo sobre a cabe\xe7a de todos, lembrando-a constantemente de que a paz e a prosperidade da Cidade de Wuling podem desaparecer em instante. \\n\\"Enquanto estivermos de p\xe9, nada estar\xe1 verdadeiramente perdido.\\"","operator.content.camille.name":"Camille","operator.content.camille.intro":"\\"Das sombras mais profundas, uma gota de sangue \xe9 extra\xedda mais uma vez.\\" \\nCamille Arno, um Guardi\xe3o de Seš\'qa especializado em lidar com incidentes violentos causados por Sarkaz ou direcionados a eles. Pertencente \xe0 mais alta elite dos Guardi\xf5es, ele domina as Artes de Originium relacionadas a sangue e \xe9 especialmente habilidoso em combater todos os tipos de feiti\xe7aria sinistra. \\nPara proteger sua terra natal, Seš\'qa, Camille prendeu in\xfameros criminosos perigosos, ainda que tenha enfrentado contratempos recorrentes em sua busca por um parente de sangue. Marcado por trai\xe7\xf5es passadas, ele se acostumou a manter uma postura fria e distante, evitando a aten\xe7\xe3o alheia — \xe9 assim que ele se protege. No entanto, quando se trata de amigos que conquistaram sua confian\xe7a, ele est\xe1 sempre disposto a revelar um lado sincero e direto. \\nNo momento, ele busca colaborar com a Endfield Industries em car\xe1ter pessoal. Ele anseia por viajar ao seu lado para terras distantes e realizar os desejos acalentados por ambos h\xe1 muito tempo. \\n\\"Honras vazias j\xe1 n\xe3o importam. Meu sangue estar\xe1 sempre com voc\xea.\\"","operator.content.mifu.name":"Mi Fu","operator.content.mifu.intro":"\\"A batalha \xe9 que nos forjou em equipe, certo?\\" \\nMi Fu, Capit\xe3 da Patrulha de Wuling, a fiel subordinada da Vice-Rainha Tianshi Zhuang Fangyi. Vencedora frequente do pr\xeamio \\"Estrelas da Vanguarda\\" de Wuling, ela ocupa o segundo lugar no ranking de poder de combate civil da cidade. Para seus colegas, ela \xe9 ao mesmo tempo a instrutora mais rigorosa e a superiora mais atenciosa. Frequentadora ass\xeddua da barraca de bolinhos de arroz doce na Avenida Fangxing, ela \xe9 uma hero\xedna para as crian\xe7as, um pesadelo para os encrenqueiros e a ru\xedna de qualquer invasor. Embora considerada uma \\"traidora\\" pela Pali\xe7ada de Qingbo, ela continua sendo a verdadeira sucessora das Artes Marciais de Qingbo. Amiga de inf\xe2ncia e rival de Tangtang, ela \xe9 uma guerreira que lutou at\xe9 o fim contra a Mar\xe9 de Praga sem jamais recuar... \\nSe quiser conhecer Mi Fu melhor, voc\xeas poder\xe3o se tornar rivais ou amigos — esses s\xe3o os dois tipos de relacionamento que ela mais valoriza. A primeira op\xe7\xe3o faz o sangue circular mais r\xe1pido; a segunda a leva a desferir cada soco sem se importar com a pr\xf3pria vida. \\nAgora, para retribuir aos amigos que lutaram ao seu lado e para enfrentar mais rivais que valham a pena combater v\xe1rias e v\xe1rias vezes, ela iniciou sua jornada de interc\xe2mbio na Endfield Industries. \\n\\"Dessa vez, eu limpo a bagun\xe7a para voc\xea.\\"","home.title.v1d3":"Esbo\xe7os de Heran\xe7as Perdidas","header.goToGame":"Ir para o Jogo","operator.content.lizhiyan.name":"Arcane","operator.content.lizhiyan.intro":"\\"Defenderei a honra dos Yinglungs.\\" \\nA capit\xe3 Arcane, da For\xe7a-Tarefa Especial de Yinglung (FTEY), h\xe1 muito tempo estacionada na Passagem de Yinglung, realiza com frequ\xeancia miss\xf5es de reconhecimento dentro da zona de exclus\xe3o. Ela \xe9 s\xe9ria, meticulosa e raramente sorri com facilidade. \\nO desastre na Zona de Exclus\xe3o do Norte de Wuling tirou tudo que Arcane tinha. Desde ent\xe3o, seu \xfanico prop\xf3sito na vida passou a ser a conten\xe7\xe3o da Fenda Gigante de Wuling. Ela j\xe1 se aventurou profundamente em sua miss\xe3o in\xfameras vezes. O \xf3dio a conduz passo a passo para as Profundezas, mas tamb\xe9m a mant\xe9m viva quando toda a esperan\xe7a parece perdida. \\nArcane re\xfane todas as qualidades que podemos esperar de um membro da FTEY: obedi\xeancia absoluta \xe0s ordens, excelente comando t\xe1tico, treinamento incans\xe1vel dia e noite e esp\xedrito indom\xe1vel. Aqueles que tamb\xe9m perderam entes queridos em desastres podem se identificar com Arcane... \\nAlgumas pessoas a consideram fria, mas, para os membros da FTEY, manter dist\xe2ncia tamb\xe9m \xe9 uma forma de prote\xe7\xe3o m\xfatua. \\n\\"Seja de vontade f\xe9rrica, mova-se como o fio de uma navalha. Yinglung vence pelo \xedmpeto.\\"","operator.content.liino.name":"Liino","operator.content.liino.intro":"\\"Brilha, brilha! Minha mais recente apresenta\xe7\xe3o est\xe1 prestes a come\xe7ar!\\" \\nLiino \xe9 uma grande \xeddolo e revela\xe7\xe3o da C\xe2mara Geral de Com\xe9rcio de Talos-II. Amada pelo p\xfablico desde sua estreia, ela \xe9 conhecida como a \\"Estrela da Manh\xe3 de La Fantoma\\".Reconhecida por seu canto primoroso e estilo de apresenta\xe7\xe3o \xfanico, seus shows frequentemente desafiam as normas e conven\xe7\xf5es do setor. \\nEla nunca deixa de proporcionar uma experi\xeancia \xfanica para seu p\xfablico, e as grandes corpora\xe7\xf5es est\xe3o sempre ansiosas para patrocinar cada um de seus shows. Embora a ascens\xe3o mete\xf3rica dessa Djall Sarkaz n\xe3o seja imune a controv\xe9rsias, todos que a veem no palco s\xe3o irremediavelmente atra\xeddos por seu brilho. \\nAtualmente, Liino est\xe1 avan\xe7ando metodicamente com seus planos para a turn\xea de shows em Talos-II. Ela acredita que far\xe1 uma apresenta\xe7\xe3o como nunca vista antes e que chegar\xe1 o dia em que brilhar\xe1 intensamente no topo do mundo. \\n\\"Oh, que fofo! Como posso te agradecer... J\xe1 sei! Vou continuar te enchendo de ingressos para shows at\xe9 ficarmos quites, que tal?\\"","operator.content.typhoea.name":"Typhoeus","operator.content.typhoea.intro":"\\"Uma boa hist\xf3ria \xe9 como um bom ca\xe7ador. Ambos miram direto no cora\xe7\xe3o.\\" \\nTyphoeus, ca\xe7adora das terras selvagens da Rhodes Island, est\xe1 curiosa com o mundo. Ela est\xe1 ansiosa para explorar lugares desabitados e inexplorados a fim de desvendar o passado esquecido. \\nEm Talos-II, muitas das lendas de Sami j\xe1 desapareceram, e apenas um punhado de Samifjod ainda se lembra delas. Typhoeus resolveu visit\xe1-las uma por uma, registrando essas mem\xf3rias fragmentadas em seu caderno. \\nAp\xf3s sua chegada \xe0 Endfield, as hist\xf3rias que ela investigou n\xe3o ficaram mais confinadas a lendas esquecidas. Ela fez muitos novos amigos e trocou hist\xf3rias com pessoas de todos os lugares. \\nE, ao perseguir essas lendas, ela tamb\xe9m est\xe1 escrevendo sua pr\xf3pria hist\xf3ria. \\nUm dia, quando todas as p\xe1ginas do seu caderno estiverem preenchidas, ela proclamar\xe1 aos amigos ao seu redor: \\n\\"As lendas nem sempre est\xe3o t\xe3o distantes da realidade... Elas podem acontecer bem ao nosso lado.\\"","operator.content.purrche.name":"Purrchena","operator.content.purrche.intro":"\\"Minha vez de... \'Miauuu!\'...Ai, como \xe9 que eu ca\xed no sono de novo?!\\" \\nPurrchena \xe9 uma grande entusiasta de sobremesas e atua como porta-voz da Funda\xe7\xe3o de Ajuda Humanit\xe1ria da S\xedndrome do Impacto Ambiental do \xc6therside. Ela ingressou no Escrit\xf3rio Comercial da Endfield Industries por recomenda\xe7\xe3o da C\xe2mara Geral de Com\xe9rcio de Talos-II (CGCT) e, desde ent\xe3o, atua como representante de liga\xe7\xe3o entre a Endfield e a CGCT para quest\xf5es de S\xedndrome do \xc6therside. \\nQuando Purrchena surgiu pela primeira vez sob os holofotes, o amor e o carinho que as pessoas demonstraram por ela a fizeram perceber a responsabilidade que carregava. Mas foi s\xf3 depois de se tornar porta-voz da Funda\xe7\xe3o e se colocar ao lado das pessoas que vivem com a S\xedndrome do \xc6therside \xe9 que ela percebeu o quanto pouco podia fazer. Embora a S\xedndrome do \xc6therside muitas vezes a fizesse adormecer sem aviso pr\xe9vio, sempre que acordava, ela partia novamente, levando consigo o amor de todos. \xc0 sua maneira, Purrchena faz com que os outros pacientes que recebem ajuda sorriam. \\n\\"J\xe1 tenho meus marshmallows e barbatanas secas ex\xf3ticas... Certo, estou pronta para ir!\\"","operator.content.endministrator2.cv.en-us":"Hyoie O\'Grady","operator.content.endministrator1.cv.en-us":"Chloe Eves","operator.content.perlica.cv.en-us":"Jane Jackson","operator.content.chen.cv.en-us":"Rebecca Hanssen","operator.content.wulfgard.cv.en-us":"Jacopo Calatroni","operator.content.arclight.cv.en-us":"Andrea Gatchalian","operator.content.ember.cv.en-us":"Rhiannon Moushall","operator.content.xaihi.cv.en-us":"Elsie Lovelock","operator.content.avywenna.cv.en-us":"Sheena May","operator.content.gilberta.cv.en-us":"Anna Devlin","operator.content.snowshine.cv.en-us":"Stephanie Southerland","operator.content.lifeng.cv.en-us":"Yung-I Chang","operator.content.laevatain.cv.en-us":"Kira Buckland","operator.content.yvonne.cv.en-us":"Clare Louise Connolly","operator.content.dapan.cv.en-us":"Jon Xu","operator.content.ardelia.cv.en-us":"Lindsay Sheppard","operator.content.akekuri.cv.en-us":"Shu Uchida","operator.content.catcher.cv.en-us":"Kevin Andrew Rivera","operator.content.estella.cv.en-us":"Risa Mei","operator.content.fluorite.cv.en-us":"Katiana Sarkissian","operator.content.antal.cv.en-us":"Jacob Craner","operator.content.alesh.cv.en-us":"Heitor Assali","operator.content.lastrite.cv.en-us":"Amber Hood","operator.content.pogranichnik.cv.en-us":"Sergey Ponomaryov","operator.content.tangtang.cv.en-us":"Jing Chen","operator.content.rossi.cv.en-us":"Giada Sabellico","operator.content.zhuangfy.cv.en-us":"Molly Zhang","operator.content.mifu.cv.en-us":"Rao Zijun","operator.content.camille.cv.en-us":"Aleks Le","operator.content.lizhiyan.cv.en-us":"Julia Gu","operator.content.liino.cv.en-us":"Maddie Matsumoto","operator.content.typhoea.cv.en-us":"Hanna Johansson","operator.content.purrche.cv.en-us":"Christine Marie Cabanos"}'),g={src:"https://web-static.hg-cdn.com/endfield/official-v4/_next/static/media/pt-br.a5fa2bfd.png"},A={lang:"pt-br",text:p,font:h,langs:i.YZ,components:{footer:t.A,SvgLogo:s.A},data:{share:[{key:"twitter",url:"https://x.com/AKEndfieldBR",icon:c.A},{key:"tiktok",url:"https://www.tiktok.com/@akendfielden",icon:d.A},{key:"facebook",url:"https://www.facebook.com/ArknightsEndfield",icon:o.A},{key:"youtube",url:"https://www.youtube.com/channel/UCowPaVRBzg8CE6K4CB6LJfw",icon:u.A},{key:"discord",url:"https://discord.gg/akendfield",icon:r.A},{key:"skport",url:"https://skport.com?hg_media=endfield_official",icon:l.A}],shop:[{key:"appStore",url:"https://apps.apple.com/app/arknights-endfield/id6752642477"},{key:"googlePlay",url:"https://play.google.com/store/apps/details?id=com.gryphline.endfield.gp"},null,null,{key:"ps5",url:"https://store.playstation.com/concept/10009205/"},{key:"windows",url:"https://launcher.gryphline.com/launcher/get_latest_launcher?appcode=TiaytKBUIEdoEwRT&ta=endfield&channel=6&sub_channel=6"},{key:"gpg",url:"https://play.google.com/pc-store/games/details?id=com.gryphline.endfield.gp"},{key:"epic",url:"https://store.epicgames.com/p/arknightsendfield-f0f167"}],operator:m},images:{"bulletin.news":g.src,"bulletin.events":g.src,"bulletin.notices":g.src,"shop.reg.appStore":"https://web-static.hg-cdn.com/endfield/official-v4/_next/static/media/appStore.8b1f09ed.png","shop.reg.googlePlay":"https://web-static.hg-cdn.com/endfield/official-v4/_next/static/media/google.c300e025.png","shop.get.appStore":"https://web-static.hg-cdn.com/endfield/official-v4/_next/static/media/appStore.b98565a5.png","shop.get.googlePlay":"https://web-static.hg-cdn.com/endfield/official-v4/_next/static/media/googlePlay.a376858f.png","home.v1d4Cele":n(36970).A.src,"home.pageTitle":n(62391).A.src,"calendar.title":n(74097).A.src,"calendar.timeline":n(37880).A.src,"calendar.content":n(8156).A.src}}};
